/**
 * ⚠⚠ FOUR TEST SEAMS THAT COULD NOT GO WITH THE CODE THEY TEST, and the reason
 * is the rule rather than convenience. Each one's body was
 * `theRealThing(() => useGameStore.getState())` — a VALUE read of this store,
 * which is precisely the import a leaf may never make. Their whole job is "call
 * the real thing with the LIVE store", so the store is where they belong. The
 * real things are exported from `app/ai/narration.ts` and wrapped here in one
 * line each; not one test call site changed, and the dependency stays one-way.
 */
export function _takeAmbientStampForTest(): AmbientStamp {
  return takeAmbientStamp(() => useGameStore.getState());
}
export function _ambientStaleReasonForTest(at: AmbientStamp): string | null {
  return ambientStaleReason(() => useGameStore.getState(), at);
}
export function _takeBankedMusingForTest(): string | null {
  return takeBankedMusing(() => useGameStore.getState());
}
export function _takeBankedSceneIntroForTest(locId: string): string | null {
  return takeBankedSceneIntro(() => useGameStore.getState(), locId);
}
