interface Concept {
  id: string;
  keywords: string[];
  title: string;
  answer: string;
}
// OTA-298 — lazy-evaluated. The 73 KB concepts.json parses on first
// findConcept() call (typically when a player types "what is X")
// instead of at module load. `_allConcepts` caches the result; the
// sort below remains per-call so the keyword-length ordering is
// always correct for the current corpus.
let _allConcepts: Concept[] | null = null;
function getAllConcepts(): Concept[] {
  if (_allConcepts) return _allConcepts;
  const conceptsData = require('../data/lore/concepts.json');
  _allConcepts = (conceptsData as { concepts: Concept[] }).concepts;
  return _allConcepts!;
}

// Match a player's "what is X / explain X / tell me about X" target text
// against the concepts knowledge base. First substring hit on any keyword
// wins; returns null if nothing matches so the caller can fall back.
/** ⚠⚠ OTA-1203 (PUNCHLIST P16, doors 2+3) — THE ONE TEACHER for a held Procedure Text.
 *  Reads the text: already-known keeps it (sellable), INT short keeps it (banked, never
 *  wasted — a purchase that ends in nothing is the punch list's founding defect), a clean
 *  read TEACHES and consumes it. Called from BOTH verbs that reach a held object —
 *  `use` (the item path) and `read` (which parses as investigate) — so the two doors
 *  cannot drift. Returns true when it consumed the action. */
function teachFromProcedureText(
  get: () => GameStore,
  set: (fn: (s: GameStore) => Partial<GameStore>) => void,
  player: PlayerCharacter,
  item: InventoryItem,
): boolean {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const AT = require('../engine/aetherTechniques') as typeof import('../engine/aetherTechniques');
  const tech = AT.findTechniqueByTextName(item.name);
  if (!tech) return false;
  if ((player.knownTechniques ?? []).includes(tech.id)) {
    get().appendLog('system', `You already carry the ${tech.name}. The text has nothing left to teach you — a collector might pay for it.`);
    return true;
  }
  const stats = effectiveStats(player);
  if (stats.intelligence < tech.intRequired) {
    get().appendLog('arbiter', `"The ${tech.name} needs INT ${tech.intRequired} and you are running ${stats.intelligence}," the Arbiter says. "Keep the text. Grow into it."`);
    return true;
  }
  set((st) => (st.player ? {
    player: {
      ...st.player,
      knownTechniques: [...(st.player.knownTechniques ?? []), tech.id],
      inventory: st.player.inventory
        .map((i) => (i.id === item.id ? { ...i, quantity: i.quantity - 1 } : i))
        .filter((i) => i.quantity > 0),
    },
  } : st));
  get().appendLog('reward', `✦ You work through the ${tech.name} procedure line by line until your hands know it. Technique learned — type \`channel ${tech.name.toLowerCase()}\`. The text is spent in the learning.`);
  void get().persist();
  return true;
}

/** OTA-1203 — resolve a typed target against the Procedure Texts actually IN THE PACK.
 *  Token-subset match; two candidates REFUSE (the P12 rule) rather than guessing which
 *  procedure the player meant to study. */
export function AT_isProcedureTextName(name: string): boolean {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const AT = require('../engine/aetherTechniques') as typeof import('../engine/aetherTechniques');
  return AT.isProcedureTextName(name);
}

function findHeldProcedureText(
  player: PlayerCharacter,
  targetText: string,
): { item: InventoryItem | null; ambiguous: string[] } {
  const texts = player.inventory.filter((i) => AT_isProcedureTextName(i.name) && i.quantity > 0);
  if (texts.length === 0) return { item: null, ambiguous: [] };
  const words = targetText.toLowerCase().split(/[^a-z0-9]+/).filter((w) => w.length >= 3);
  const hits = texts.filter((i) => {
    const toks = i.name.toLowerCase().split(/[^a-z0-9]+/);
    return words.length > 0 && words.every((w) => toks.includes(w));
  });
  if (hits.length === 1) return { item: hits[0]!, ambiguous: [] };
  if (hits.length > 1) return { item: null, ambiguous: hits.map((i) => i.name) };
  return { item: null, ambiguous: [] };
}

/** OTA-1214 — ONE completion body for a lead, shared by the kill-name path
 *  (OTA 011), the at-site verb path, and the at-site kill path — three doors,
 *  one settlement, so reward and state can never drift by entry point. */
function resolveLeadCompletion(
  get: () => GameStore,
  set: (fn: (s: GameStore) => Partial<GameStore>) => void,
  lead: NonNullable<PlayerCharacter['activeQuests']>[number],
): void {
  const reward = lead.reward;
  if (reward.type === 'currency' && reward.amount) {
    set((s) => (s.player ? { player: { ...s.player, tc: s.player.tc + reward.amount! } } : s));
    get().appendLog('reward', `Lead resolved: ${lead.objective.verb} ${lead.objective.target}. +${reward.amount} TC.`);
  } else {
    get().appendLog('reward', `Lead resolved: ${lead.objective.verb} ${lead.objective.target}. (${reward.label})`);
  }
  set((s) =>
    s.player
      ? {
          player: {
            ...s.player,
            activeQuests: s.player.activeQuests.map((q) =>
              q.id === lead.id ? { ...q, state: 'completed' as const } : q,
            ),
          },
        }
      : s,
  );
}

/** ⚠⚠ OTA-1213 — DETERMINISTIC STAGE TRIGGERS. Owner, stuck on the Bog Dragon at
 *  stage 2/7 with the card reading "You're at Mud Seas": "I investigated
 *  everything in the area, I hit investigate when the area was empty, nothing
 *  is happening... we need to make sure every stage of every mission has a
 *  working trigger."
 *
 *  THE OLD CONTRACT, written out, was indefensible: a stage advanced only when
 *  the matching verb happened to reach the generic SKILL ROLL (most investigate
 *  inputs break earlier — chip flavor, already-searched refusals, hooks, empty
 *  modals) AND the d20 passed (his INT 4 failed most rolls) — and NO input in an
 *  exhausted tile reaches the roll at all, so the stage was unreachable from
 *  the exact place the card told him to stand. Silently. And with no location
 *  gate, a lucky roll advanced "investigate the area" from across the map.
 *
 *  THE NEW CONTRACT: performing the stage's verb IS the trigger.
 *    - Hunts: the verb must be performed AT the hunt's anchor tile — the SAME
 *      id the card's "You're at" line and the atlas pin read (huntAnchorId).
 *      At the wrong place, the matching verb draws a throttled routing line
 *      instead of silence, so the player is never left tapping into a void.
 *    - Mysteries / storylines: verb alone (their marker anchors are faction
 *      hubs — turn-in doors, not field sites; gating on them would be wrong).
 *    - Combat gating unchanged: exploration kinds hold in combat; escape /
 *      attack_provoke / boss work mid-fight. Kind→intent maps preserved
 *      verbatim from the old matchers, quirks included.
 *  No dice anywhere in it: the stage IS the content, and a die that can only
 *  delay or hide content earns nothing (the OTA-053 auto-advance note already
 *  said stages with no check are narration; now the check is the VERB). */
/** ⚠⚠ OTA-1215 — THE BURST GUARD. INVESTIGATE ALL fires one submit per chip in
 *  a single loop WITHOUT awaiting, so every submit's synchronous prefix — including
 *  advanceStagesOnIntent — runs before the first queued advance lands. On the
 *  owner's device, three chips meant three matches against the SAME stage and a
 *  3-stage jump: the diplomacy beat skipped and the mid-hunt boss spawned into the
 *  marsh unannounced ("I hit it and was confronted with the Bog dragon"). One
 *  advance may be in flight per mission at a time; the burst's extras are dropped,
 *  and the next real action re-reads the fresh stage. */
const stageAdvancesInFlight = new Set<string>();
/** OTA-1687 — the intents a stage can be paid by (questStage.payingIntent's
 *  range, minus escape, which is combat). A typed one of these on a stage's
 *  own cell that pays nothing draws the ask the stage prints on arrival. */
const STAGE_VERB_INTENTS = new Set<string>(['investigate', 'diplomacy', 'attack', 'stealth', 'cast']);
const LOOK_VERBS = new Set<string>(['look', 'l', 'glance', 'peek', 'observe', 'watch']);

/** ⚠⚠ P19 — HAND OVER WHAT THE STAGES IN [from, to) PROMISED. Two callers need this and
 *  they need it to behave identically:
 *
 *   • `advanceHunt`, for the stage that just closed;
 *   • ACCEPT, for the null `inciting_hook` stages it skips past.
 *
 *  ⚠⚠ The second one is a real bug the honest walker caught. `firstActionableHuntStage`
 *  starts the record PAST every leading null stage (OTA-1219 — hunts had no auto-consume
 *  loop and wedged forever without it), so a stage-0 grant was never awarded by anything.
 *  Every hunt opens with the giver handing you a token; the token simply never arrived,
 *  and stage 1 then refused for the rest of time. A silent skip, exactly the class of
 *  failure this whole item exists to end.
 *
 *  ⚠ Granted ONCE, guarded on what is already in the pack — a boss stage freezes for the
 *  kill and re-runs this path, and a quest item that duplicates per visit is a currency
 *  press wearing a story hat. */
export function grantStageItems(
  get: () => GameStore,
  set: (fn: (s: GameStore) => Partial<GameStore>) => void,
  title: string,
  stages: ReadonlyArray<{ grants?: { item: string; quantity?: number } }>,
  from: number,
  to: number,
  // ⚠⚠ Returns how many grants actually LANDED (accepted > 0). The caller must know,
  // because a landed grant is state the REST OF THIS ACTION can destroy: the generic verb
  // handlers write inventory back from snapshots taken before the heal ran. A heal that
  // handed something over has to consume the whole action — see advanceStagesOnIntent.
): number {
  let landed = 0;
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const QS = require('../engine/questStage') as typeof import('../engine/questStage');
  for (let i = Math.max(0, from); i < Math.min(to, stages.length); i++) {
    const g = stages[i]?.grants;
    if (!g) continue;
    const qty = g.quantity ?? 1;
    const live = get().player;
    if (!live || QS.countInPack(live.inventory, g.item) >= qty) continue;
    const res = grantItem(live.inventory, {
      id: freshInstanceId(g.item.toLowerCase().replace(/[^a-z0-9]+/g, '_')),
      name: g.item, kind: 'misc', quantity: qty, tags: ['quest', 'mission'],
      description: `Carried for ${title}.`,
    });
    // ⚠⚠ CHECK BEFORE YOU CLAIM. `grantItem` clamps to a per-name cap and can accept ZERO,
    // returning the pack unchanged — and the first version of this logged "✦ … mission
    // item." regardless. A receipt for an item that never arrived is worse than silence:
    // the player reads that they have it and the next stage refuses them for not having it,
    // with the log insisting otherwise. Same class as the auto-route line that announced a
    // course `setTravelCourse` had already refused.
    if (res.accepted <= 0) {
      get().appendLog('arbiter', `The Arbiter frowns at your pack. "No room for ${g.item}. Make some — ${title} does not move without it."`);
      continue;
    }
    set((st) => (st.player ? { player: { ...st.player, inventory: res.inventory } } : st));
    get().appendLog('reward', `✦ ${qty > 1 ? `${qty}× ` : ''}${g.item} — mission item.`);
    landed += 1;
  }
  return landed;
}

/** ⚠⚠ P19 — DOES A TRACKED CONTRACT WANT THIS EXACT VERB, ON THIS EXACT GROUND, RIGHT NOW?
 *
 *  Found by the honest walker, twice. A wandering trader rolled onto a hunt's `diplomacy`
 *  stage tile and TALK went to the trader; then two storyline turn-ins — both `boss`
 *  stages, and a storyline `boss` is matched by DIPLOMACY — landed at an outpost where a
 *  named vendor stands permanently, and the same branch ate the verb every time.
 *  `advanceStagesOnIntent` runs near the END of submitPlayerAction, long after the vendor
 *  and wanderer parley branches, and those branches return early. So the player stood in
 *  exactly the right place, typed exactly the right word, and got "you let the conversation
 *  go" forever, with nothing in the game able to say why.
 *
 *  ⚠ It is the STAGE that gets priority, not the merchant: the stall is ambient and will
 *  still be there afterwards; the stage is the reason the player walked here. Deliberately
 *  narrow — same ground, same verb, tracked contract, not in combat.
 *
 *  ⚠⚠ OTA-1588 — THE checkKind→intent MAP IS NO LONGER COPIED HERE. This comment used to
 *  read "MUST MIRROR EACH FAMILY'S MATCHER, quirks included" — which is a warning that one
 *  question was being answered in four places, and the fourth copy (OTA-1586's arrival
 *  line) got it wrong on thirty stages. `QS.payingIntent(family, stage)` is the single
 *  answer now: a MYSTERY's `boss` is paid by INVESTIGATE and a STORYLINE's by DIPLOMACY,
 *  and that fact lives in exactly one file. */
function stageAwaitsIntentHere(get: () => GameStore, intent: Intent): boolean {
  const player = get().player;
  if (!player) return false;
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const QS = require('../engine/questStage') as typeof import('../engine/questStage');
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const CM = require('../engine/contractMarkers') as typeof import('../engine/contractMarkers');
  // ⚠ OTA-1637 — "here" is the CELL, the same test the arrival doors run.
  const wants = (stage: { checkKind: string | null } | undefined, family: MissionFamily): boolean =>
    QS.payingIntent(family, stage) === intent;

  for (const rec of player.activeHunts ?? []) {
    if (rec.tracked === false) continue;
    const def = findHuntById(rec.id);
    const stage = def?.stages[rec.stage];
    if (!def || !wants(stage, 'hunt')) continue;
    if (standingAtLocation(player, QS.stageLocationId(stage, CM.huntAnchorId(def), CM.resolvePosterLocation))) return true;
  }
  for (const rec of player.activeMysteries ?? []) {
    if (rec.tracked === false) continue;
    const def = findMysteryById(rec.id);
    const stage = def?.stages[rec.stage];
    if (!def || !wants(stage, 'mystery')) continue;
    if (standingAtLocation(player, QS.stageLocationId(stage, CM.contractAnchorId(def), CM.resolvePosterLocation))) return true;
  }
  for (const rec of player.activeStorylines ?? []) {
    if (rec.tracked === false) continue;
    const def = findStorylineById(rec.id);
    const stage = def?.stages[rec.stage];
    if (!def || !wants(stage, 'storyline')) continue;
    if (standingAtLocation(player, QS.stageLocationId(stage, CM.contractAnchorId(def), CM.resolvePosterLocation))) return true;
  }
  return false;
}

// ⚠⚠ RETURNS TRUE WHEN THE ACTION IS CONSUMED AND MUST NOT FALL THROUGH.
//
// Found by the storyline walker during the HAL map audit, and it is a REAL wedge a player
// can hit, not a harness artifact. The chain, verbatim from the probe log: the catch-up
// heal grants a missing mission item and says "Go again" — but this function was `void`,
// so submitPlayerAction fell through to the generic verb handler. The generic INVESTIGATE
// beat rolled loot and wrote the inventory back from a snapshot taken BEFORE the heal —
// the healed item vanished — and it also consumed the tile's once-only area search. Second
// attempt: item missing again, heal re-fires, and "You already searched the area" eats the
// verb. The stage is now unwinnable on its own ground.
//
// OTA-1330 (the mysteries pass) stopped the heal from ADVANCING in the same action, for exactly this stale-
// snapshot race. It did not stop the ACTION. Same hole, one layer out. The rule now: a
// heal that landed anything consumes the whole action — "Go again" costs one tap and the
// repeat runs on clean state through the normal path.
function advanceStagesOnIntent(
  get: () => GameStore,
  set: (fn: (s: GameStore) => Partial<GameStore>) => void,
  intent: Intent,
  resolvedNoun?: string | null,
  verb?: string | null,
): boolean {
  const player = get().player;
  const currentScene = get().currentScene;
  if (!player || !currentScene) return false;
  // ⚠⚠⚠ OTA-1630 — THE CHIP IS NOT THE MISSION. Owner's log: "investigate the mud"
  // resolved to the Aether Mud chip, and a tracked hunt whose stage pays on
  // `investigate` claimed it AWAY from its ground — "Not here. The Bog Dragon
  // points elsewhere" — so the chip was never touched and stayed lit. A verb that
  // NAMES a scene noun is aimed at that noun; the "Not here" claim below stays out
  // of it. ⚠ ON the anchor a chip burst still pays the stage once (OTA-1215).
  const namesChip = !!resolvedNoun && (currentScene.ambientNouns ?? []).some((n) => n.toLowerCase() === resolvedNoun.toLowerCase());
  const inCombat = (currentScene.enemies?.length ?? 0) > 0;
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { huntAnchorId } = require('../engine/contractMarkers') as typeof import('../engine/contractMarkers');
  // ⚠⚠⚠ OTA-1588 — ONE ANSWER TO "WHAT VERB PAYS THIS STAGE", ASKED PER FAMILY.
  // The three matchers below each carried their own copy of the checkKind→intent
  // map, quirks included, and `stageAwaitsIntentHere` carried a fourth. A fifth
  // reader — OTA-1586's arrival line — guessed, and got thirty stages wrong.
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const QSV = require('../engine/questStage') as typeof import('../engine/questStage');

  const huntMatch = (player.activeHunts ?? [])
    .map((rec) => ({ rec, def: findHuntById(rec.id) }))
    .find(({ rec, def }) => {
      if (!def) return false;
      if (rec.tracked === false) return false; // DEACTIVATED (paused) — frozen
      const next = def.stages[rec.stage];
      if (!next) return false;
      if (QSV.payingIntent('hunt', next) !== intent) return false;
      // ⚠⚠ OTA-1217 — EVERY ROW BUT ESCAPE IS AN OUT-OF-COMBAT DELIBERATE ACTION
      // (escape alone stays in-combat: fleeing IS combat). Without the guard, the
      // frozen apex stage (OTA-796) re-matched on EVERY swing of the boss fight
      // itself — each attack re-ran advanceHunt, which re-spawned the boss at
      // FULL HP, reset the range, and re-logged the apex narration. The fight
      // literally could not be won. ⚠ OTA-1588 kept this guard byte for byte and
      // replaced only the verb table above it.
      return next.checkKind === 'escape' ? true : !inCombat;
    });
  if (huntMatch && huntMatch.def) {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const QS = require('../engine/questStage') as typeof import('../engine/questStage');
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { resolvePosterLocation } = require('../engine/contractMarkers') as typeof import('../engine/contractMarkers');
    // ⚠⚠ P19 — A STAGE CAN NOW STAND SOMEWHERE OF ITS OWN. `huntAnchorId` reads the
    // contract DEF, so every stage of a seven-stage hunt shared one tile and there was
    // nothing to route BETWEEN — the owner's *"it didn't auto route me to the next
    // stage"*. A stage that names its own ground gets it; one that doesn't keeps the
    // contract anchor, which is the old behaviour and the default.
    const stageDefNow = huntMatch.def.stages[huntMatch.rec.stage];
    const anchor = QS.stageLocationId(stageDefNow, huntAnchorId(huntMatch.def), resolvePosterLocation);
    // ⚠ OTA-1637 — the verb pays on the CELL, the same test the arrival doors run.
    if (standingAtLocation(player, anchor)) {
      // ⚠⚠ AND THE PACK IS CHECKED BEFORE THE VERB COUNTS. Owner: *"the next stage spoke
      // about giving the book to his sister. who's sister? and what book?"* A stage that
      // asks for a thing now REFUSES until you hold it, and the refusal names the thing —
      // silence here is what made the prose read as broken.
      if (!QS.stageRequirementMet(stageDefNow, player.inventory)) {
        // ⚠⚠ P19 — HEAL BEFORE YOU REFUSE. A record can legitimately be standing on a
        // stage whose prerequisite was never handed over: a save accepted before this OTA,
        // or the faction accept door, which writes the record directly. Refusing those
        // forever would turn a fixed hunt into a bricked one — the softlock is worse than
        // the bug it replaces. So: award anything an EARLIER stage of this hunt promised
        // and the pack has never held, then re-check. Idempotent (guarded on pack count),
        // so on the happy path it does nothing at all.
        // ⚠ It re-checks rather than assuming: if the item is still missing after the
        // catch-up, the refusal below is the honest answer and the player still gets told
        // exactly what they need.
        const landed = grantStageItems(get, set, huntMatch.def.title, huntMatch.def.stages, 0, huntMatch.rec.stage);
        // ⚠⚠ THE HEAL HANDS OVER AND STOPS — it does NOT also advance on this action.
        // Advancing here raced the rest of `submitPlayerAction`: the action's own loot
        // write captures `player` at the top of the call and writes the inventory back
        // whole, so a mission item granted mid-flight was silently clobbered by the next
        // handler's stale snapshot. Measured on the walker — the receipt printed and the
        // item was gone one line later. Repairing a save is not the hot path; costing it
        // one extra tap buys a write that cannot be lost.
        if (QS.stageRequirementMet(stageDefNow, get().player?.inventory)) {
          get().appendLog('arbiter', `The Arbiter checks your pack and finds what ${huntMatch.def.title} wants. "You had it after all. Go again."`);
          // ⚠⚠ The heal LANDED something — the action ends here, or the generic verb
          // handler's stale-snapshot loot write destroys what was just granted.
          return true;
        }
        const line = QS.stageRequirementLine(stageDefNow!, huntMatch.def.title);
        const seen = get().gameLog.slice(-30).some((e) => e.text === line);
        if (!seen) get().appendLog('arbiter', line);
        // ⚠ A PARTIAL heal (granted A, still missing B) is state worth protecting too —
        // fall through only when nothing landed at all.
        return landed > 0;
      }
      const flightKey = `hunt:${huntMatch.rec.id}`;
      if (!stageAdvancesInFlight.has(flightKey)) {
        stageAdvancesInFlight.add(flightKey);
        void Promise.resolve().then(() => {
          try { get().advanceHunt(huntMatch.rec.id); } finally { stageAdvancesInFlight.delete(flightKey); }
        });
      }
    } else if (!inCombat && !namesChip) {
      // The verb matched, the ground didn't — say so instead of the old silence.
      // Throttled: skip if the same line is already in the recent log.
      const line = wrongGroundLine(player, anchor, huntMatch.def.title);
      const recent = get().gameLog.slice(-30).some((e) => e.text === line);
      if (!recent) get().appendLog('arbiter', line);
    }
  } else if (inCombat) {
    // ⚠⚠ P19 — AND THE COMBAT GATE STOPS BEING SILENT. Owner: *"there should be no
    // attacks on the stage roles unless it's the actual hunt tile and it's the beast."*
    // Every non-boss stage verb is gated on `!inCombat` in the matcher above, so at a
    // danger-4/5 anchor the player performs the RIGHT action, something is mid-swing at
    // them, and nothing happens with no explanation at all. It is the correct rule — you
    // cannot study a room while it is trying to kill you — but it has to say so.
    // ⚠ OTA-1624 — and it speaks for EVERY family now (the mystery and storyline
    // branches below were silent in combat). One reader: missionTrace.stalledInCombat.
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const stalled = (require('../engine/missionTrace') as typeof import('../engine/missionTrace')).stalledInCombat(player, intent);
    if (stalled) {
      const line = `The Arbiter keeps one eye on the fight. "That is the right move for ${stalled.title} — but not with something on you. Put this down first."`;
      const recent = get().gameLog.slice(-30).some((e) => e.text === line);
      if (!recent) get().appendLog('arbiter', line);
    }
  }

  const mysteryMatch = (player.activeMysteries ?? [])
    .map((rec) => ({ rec, def: findMysteryById(rec.id) }))
    .find(({ rec, def }) => {
      if (!def) return false;
      if (rec.tracked === false) return false; // DEACTIVATED (paused) — frozen
      const next = def.stages[rec.stage];
      if (!next) return false;
      // ⚠ OTA-1588 — a MYSTERY's `boss` is paid by INVESTIGATE, and that fact now
      // lives once, in questStage.payingIntent, instead of here and in three
      // other places that had to be kept in step by hand.
      return QSV.payingIntent('mystery', next) === intent;
    });
  if (mysteryMatch && mysteryMatch.def && !inCombat) {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const QS = require('../engine/questStage') as typeof import('../engine/questStage');
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const CM = require('../engine/contractMarkers') as typeof import('../engine/contractMarkers');
    // ⚠⚠ P19 — A MYSTERY NOW HAPPENS SOMEWHERE. Measured before touching it: the mystery
    // matcher checked the VERB and NOTHING ELSE — no location test of any kind, where the
    // hunt branch has gated on `currentLocationId === anchor` since OTA-1213. So all 18
    // mysteries could be walked end to end from one tile without ever travelling, which is
    // the opposite failure from the hunts and just as bad: the prose names a place, the
    // engine never asked you to go there, and 26 of 36 named locations went unvisited.
    const stageNow = mysteryMatch.def.stages[mysteryMatch.rec.stage];
    const ground = QS.stageLocationId(stageNow, CM.contractAnchorId(mysteryMatch.def), CM.resolvePosterLocation);
    if (!standingAtLocation(player, ground)) {
      const line = wrongGroundLine(player, ground, mysteryMatch.def.title);
      const recent = get().gameLog.slice(-30).some((e) => e.text === line);
      if (!recent && !namesChip) get().appendLog('arbiter', line);
      return false; // nothing granted — the generic beat may still play
    }
    // ⚠ Same heal-then-refuse the hunts got: a record already in flight when this shipped
    // never received the earlier stages' grants, and refusing it forever would brick a
    // mystery that used to work. Award the missing prefix, re-check, and only then refuse.
    if (!QS.stageRequirementMet(stageNow, player.inventory)) {
      const landed = grantStageItems(get, set, mysteryMatch.def.title, mysteryMatch.def.stages, 0, mysteryMatch.rec.stage);
      // ⚠⚠ Hands over and STOPS — see the hunt branch. Advancing on the same action races
      // the caller's own inventory write and loses the item that was just granted.
      if (QS.stageRequirementMet(stageNow, get().player?.inventory)) {
        get().appendLog('arbiter', `The Arbiter checks your pack and finds what ${mysteryMatch.def.title} wants. "You had it after all. Go again."`);
        return true; // heal landed — consume the action (see the function note)
      }
      const line = QS.stageRequirementLine(stageNow!, mysteryMatch.def.title);
      const seen = get().gameLog.slice(-30).some((e) => e.text === line);
      if (!seen) get().appendLog('arbiter', line);
      return landed > 0; // a PARTIAL heal is state worth protecting
    }
    const flightKey = `mystery:${mysteryMatch.rec.id}`;
    if (!stageAdvancesInFlight.has(flightKey)) {
      stageAdvancesInFlight.add(flightKey);
      void Promise.resolve().then(() => {
        try { get().advanceMystery(mysteryMatch.rec.id); } finally { stageAdvancesInFlight.delete(flightKey); }
      });
    }
  }

  const storyMatch = (player.activeStorylines ?? [])
    .map((rec) => ({ rec, def: findStorylineById(rec.id) }))
    .find(({ rec, def }) => {
      if (!def) return false;
      if (rec.tracked === false) return false; // DEACTIVATED (paused) — frozen
      const next = def.stages[rec.stage];
      if (!next) return false;
      // ⚠ OTA-1588 — a STORYLINE's `boss` is paid by DIPLOMACY. Same single answer.
      return QSV.payingIntent('storyline', next) === intent;
    });
  if (storyMatch && storyMatch.def && !inCombat) {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const QS = require('../engine/questStage') as typeof import('../engine/questStage');
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const CM = require('../engine/contractMarkers') as typeof import('../engine/contractMarkers');
    // ⚠⚠ P19 — THE LAST FAMILY GETS ITS GROUND. Storylines had the same hole mysteries
    // did: the matcher checked the VERB and nothing else, so a nine-chapter faction arc
    // could be walked start to finish standing on one tile. These are the LONGEST chains
    // in the game (6-9 stages, 93 in total) and the ones most obviously written as a
    // journey — which made the gap the widest here of anywhere.
    const stageNow = storyMatch.def.stages[storyMatch.rec.stage];
    const ground = QS.stageLocationId(stageNow, CM.contractAnchorId(storyMatch.def), CM.resolvePosterLocation);
    if (!standingAtLocation(player, ground)) {
      const line = wrongGroundLine(player, ground, storyMatch.def.title);
      const recent = get().gameLog.slice(-30).some((e) => e.text === line);
      if (!recent && !namesChip) get().appendLog('arbiter', line);
      return false; // nothing granted — the generic beat may still play
    }
    // ⚠ Heal-then-refuse, and the heal HANDS OVER AND STOPS — granting mid-action races
    // the caller's own inventory write and loses what it just gave. See the hunt branch.
    if (!QS.stageRequirementMet(stageNow, player.inventory)) {
      const landed = grantStageItems(get, set, storyMatch.def.title, storyMatch.def.stages, 0, storyMatch.rec.stage);
      if (QS.stageRequirementMet(stageNow, get().player?.inventory)) {
        get().appendLog('arbiter', `The Arbiter checks your pack and finds what ${storyMatch.def.title} wants. "You had it after all. Go again."`);
        return true; // heal landed — consume the action (see the function note)
      }
      const line = QS.stageRequirementLine(stageNow!, storyMatch.def.title);
      const seen = get().gameLog.slice(-30).some((e) => e.text === line);
      if (!seen) get().appendLog('arbiter', line);
      return landed > 0; // a PARTIAL heal is state worth protecting
    }
    const flightKey = `storyline:${storyMatch.rec.id}`;
    if (!stageAdvancesInFlight.has(flightKey)) {
      stageAdvancesInFlight.add(flightKey);
      void Promise.resolve().then(() => {
        try { get().advanceStoryline(storyMatch.rec.id); } finally { stageAdvancesInFlight.delete(flightKey); }
      });
    }
  }

  // ⚠⚠ OTA-1687 — THE WRONG VERB ON THE RIGHT GROUND SAYS WHAT THE GROUND
  // WANTS. Every matcher above speaks when the verb matches and the ground
  // does not ("Not here … points elsewhere"). The contrary walker typed
  // "negotiate" and "attack" on the Cradle of Dusk — a search stage, boots on
  // the cell — and nothing about the hunt was said. A stage verb that no
  // tracked stage pays, typed on a stage's own cell, now draws the ask that
  // stage prints on arrival. Only stage verbs (a cardinal or a "look" is not
  // an attempt at the stage), never in combat, never for a chip's own noun.
  // ⚠ "look around" parses as INVESTIGATE (verb=look); a look is not an
  // attempt at the stage, so the look family never draws the line.
  if (!inCombat && !namesChip && !huntMatch && !mysteryMatch && !storyMatch && STAGE_VERB_INTENTS.has(intent) && !LOOK_VERBS.has((verb ?? '').toLowerCase())) {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const under = (require('../engine/missionTrace') as typeof import('../engine/missionTrace')).stageUnderfoot(player);
    if (under && under.ask && under.intent !== intent) {
      const line = `The Arbiter taps the slate. "Not that. ${under.title} wants you to ${under.ask} here."`;
      const recent = get().gameLog.slice(-30).some((e) => e.text === line);
      if (!recent) get().appendLog('arbiter', line);
    }
  }

  // ⚠⚠ OTA-1214 — LEADS. At the lead's own pinned location, the objective's
  // verb-matched intent completes it. Before this, the only trigger was
  // kill-verb name matching, which not one of the 18 authored objectives could
  // ever satisfy — the whole family accumulated forever.
  if (!inCombat) {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { LEAD_VERB_TRIGGERS } = require('../engine/questGenerator') as typeof import('../engine/questGenerator');
    const readyLeads = (player.activeQuests ?? []).filter(
      (q) =>
        (q.state === 'open' || q.state === 'in_progress') &&
        q.tracked !== false &&
        q.location?.id === player.currentLocationId &&
        (LEAD_VERB_TRIGGERS[q.objective.verb.toLowerCase()]?.intents ?? []).includes(intent),
    );
    for (const lead of readyLeads) resolveLeadCompletion(get, set, lead);
  }
  return false;
}

/** OTA-1206 — what the torchlight flags as worth investigating in the CURRENT
 *  scene, resolved against this room's own memory (read notes and harvested
 *  perches don't glow). One caller shape for both torch paths — the aimed
 *  charge and the no-lead sweep — so the mark can't mean two things. */
function computeArbiterEye(get: () => GameStore): string[] {
  const scene = get().currentScene;
  const player = get().player;
  if (!scene || !player) return [];
  const roomKey = makeRoomKey(
    player.currentLocationId, scene.microMicroId, player.mapX, player.mapY, player.hubRoomId,
  );
  const mem = get().worldMemory.visitedRooms?.[roomKey];
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { arbiterEyeNouns } = require('../engine/arbiterEye') as typeof import('../engine/arbiterEye');
  return arbiterEyeNouns({
    displayedNouns: scene.displayedAmbientNouns ?? scene.ambientNouns ?? [],
    hooks: scene.hooks ?? [],
    nounPlacements: scene.nounPlacements ?? null,
    flavorExhaustedNouns: mem?.flavorExhaustedNouns ?? [],
    searchedAmbientNouns: mem?.searchedAmbientNouns ?? [],
  });
}

/** ⚠⚠ OTA-1198 (PUNCHLIST P17) — one place that decides a lore answer was EARNED.
 *
 *  Three different paths answer a lore question (keyword concepts, the embedder, and the
 *  offline bank match), and before this only the middle one credited the player. Rather
 *  than repeat the bookkeeping three times — which is how two of them would drift back out
 *  of agreement — they all call this.
 *
 *  ⚠ DISTINCT CONCEPTS, NOT ASKS. The old tick counted every answer, so asking the same
 *  question three times earned the title. A title called Scholar of Forgotten Lore should
 *  mean three different things read; growth-through-repetition has been closed twice this
 *  session already and opening two more doors onto it would have made a farm of it. */
function creditLoreRead(get: StoreGet, set: StoreSet, conceptKey: string): void {
  const seen = get().player?.loreConceptsRead ?? [];
  if (seen.includes(conceptKey)) return;
  set((st) => (st.player
    ? { player: { ...st.player, loreConceptsRead: [...(st.player.loreConceptsRead ?? []), conceptKey] } }
    : st));
  // arb45 — Scholar of Forgotten Lore: each deciphered text counts (3 needed).
  recordTitleProgress(get, set, { loreRead: 1 });
}

/** ⚠ OTA-1199 (PUNCHLIST P15) — this place's own authored loot rows, for the area-search
 *  substitution. Resolved through `ladderLootPool` so the unique-quest-reward exclusion and
 *  the name resolution are the SAME ones `pickLootFromLadder` uses. Returns [] when the
 *  scene has no ladder micro-micro, which leaves search behaving exactly as before. */
/** ⚠ EXPORTED for the live wiring test. The unit suite builds a `siteLoot` array by hand,
 *  so it proves the roller and says nothing about whether the STORE hands one over — if
 *  this returned [] on every real scene the feature would ship doing nothing with green
 *  tests behind it (the OTA-1186 lesson). Asserting on a search OUTCOME cannot cover it
 *  either: a noun can only be searched once per room, so a sampling loop is refused after
 *  the first try. This is the seam, so this is what the test reads. */
export function siteLootForScene(get: StoreGet): { name: string; rarity: import('../engine/types').Rarity }[] {
  const mmId = get().currentScene?.microMicroId;
  if (!mmId) return [];
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const enc = require('../engine/encounter') as typeof import('../engine/encounter');
  return enc.ladderLootPool(findMicroMicroAnywhere(mmId));
}

// (exported for the OTA-1483 suite — the matcher's ranking rule is the subject
// under test, and driving 178 concepts through the parser to reach it would
// test the parser, not the rule.)
export function findConcept(targetText: string | undefined): Concept | null {
  if (!targetText) return null;
  const t = targetText.toLowerCase();
  if (!t.trim()) return null;
  // ⚠⚠ OTA-1483 — THE LONGEST **MATCHED** KEYWORD WINS, not any keyword of the
  // concept that HAPPENS TO OWN a long one. The old loop sorted CONCEPTS by
  // their longest keyword and then, walking that order, returned on ANY keyword
  // hit — so a concept could win the race on the strength of a 20-character
  // keyword and then match on its 8-character one. From the owner's 4.32.11
  // log: "aetheric abilities" answered with the AETHERIC DAMAGE TYPE
  // ("Invisible, concussive force…") because the damage concept's bare
  // "aetheric" matched and nothing more specific was even consulted — the
  // comment above the sort ("so 'burn damage' matches before 'burn'") claimed a
  // property the code did not have.
  //
  // Now every (concept, keyword) pair is scored by the length of the keyword
  // that ACTUALLY MATCHED, and the longest wins. Ties keep catalogue order, so
  // existing single-keyword resolutions are unchanged.
  let best: Concept | null = null;
  let bestLen = 0;
  for (const c of getAllConcepts()) {
    for (const kw of c.keywords) {
      const k = kw.toLowerCase();
      if (k.length > bestLen && t.includes(k)) {
        best = c;
        bestLen = k.length;
      }
    }
  }
  return best;
}

const allLocations = locationsData as Location[];

/** How many ambient props a single scene/tile surfaces as Search /
 *  Approach / Salvage / INVESTIGATE chips (and in look-around). Was 8;
 *  dropped to 5 because a room full of 8-10 pokeable nouns turned
 *  INVESTIGATE into a tap-grind with no "investigate all" escape hatch.
 *  Fewer props = fewer taps to clear; the per-noun find chance is
 *  unchanged, so the odds a room shows the player something still hold. */
const AMBIENT_DISPLAY_CAP = 8;

// OTA-434 — unique inventory instance ids. Many grant sites minted ids as
// `${prefix}_${Date.now()}`, so two items granted in the SAME millisecond (craft
// + craft, a multi-item loot drop, buy-then-buy) collided on one id. Duplicate
// ids break every per-instance operation that keys on id — equip-by-id,
// repair-by-id (OTA-431), durability wear, and per-instance temper stats
// (OTA-427) — silently acting on the wrong copy. This monotonic counter makes
// each id unique regardless of clock resolution.
let _itemInstanceSeq = 0;
export function freshInstanceId(prefix: string): string {
  return `${prefix}_${Date.now()}_${(_itemInstanceSeq++).toString(36)}`;
}

/** Are these two inventory rows the SAME stackable unit — i.e. can a peeled unit
 *  from one merge into the other? Name + kind must match, and neither row may
 *  carry per-instance identity (a coating, tempered stats, or fused uniqueStats)
 *  that a merge would silently erase. Same rule grantItem uses on pickup.
 *
 *  OTA-1097 — hoisted to module scope. It was defined THREE times as an
 *  identical local closure (fusion reserve, quest reserve, and now the bulk
 *  fusion reserve). Three copies of a merge-safety predicate is three chances
 *  for one of them to fall behind when a new per-instance field lands. */
export function sameStackUnit(a: InventoryItem, b: InventoryItem): boolean {
  return a.name === b.name && a.kind === b.kind
    && !a.coating && !b.coating
    && !a.instanceStats && !b.instanceStats
    && !a.uniqueStats && !b.uniqueStats;
}


/** True only when the player is genuinely STANDING IN their current named
 *  location — on its map anchor (or inside one of its hub rooms), and not
 *  mid-journey.
 *
 *  Why this exists: `currentLocationId` flips to a new place only on
 *  ARRIVAL, so it lingers as the DEPARTURE capital for the whole of a
 *  plotted trip, and it also stays put while you cardinally wander off the
 *  anchor into open ground. Any check that keys purely off currentLocationId
 *  — Core recovery, Core-Guardian summon — would otherwise fire miles from
 *  the city: leave a capital whose Core you haven't taken, throw a punch at
 *  a wandering Mudling (a Monarch's gate intent is `attack`), and its
 *  Guardian would materialise in the wilderness. Every arrival snaps the
 *  player to WORLD_MAP_CENTER, so anchor + no travelTarget == "really here". */
// ⚠⚠ OTA-1480 — MOVED TO app/engine/standingAt.ts AND EXPORTED. It was private to
// this file, which is why both SUMMON chips ended up carrying hand-rolled copies
// under comments reading "Mirror isStationedAtNamedLocation". A predicate that is
// private to one file and needed by three is not private, it is copied. The leaf
// version also reads the AUTHORITATIVE grid cell instead of the re-centered visual
// frame, matching `playerGridCell` and `standingAtLocation`; the suite proves the
// two spellings agree across every reachable state rather than assuming it.
const isStationedAtNamedLocation = stationedAtNamedLocation;

/** OTA-417 — true when the player is INDOORS (a hub room or a building interior).
 *  The wandering-lead hooks (HOOK_PLANTS) are all OUTDOOR sightings — smoke in
 *  the distance, a giant on the ridge, a submerged steeple — so none of them may
 *  be planted here. Investigating a candle in a house must not surface "a figure
 *  too tall to be human watches you from the far ridge" (the player's report).
 *
 *  Pure predicate (exported for tests). */
export function readsIndoorsForHooks(p: {
  hubRoomId?: string | null;
  activeBuildingId?: string | null;
  travelTarget?: { locationId: string } | null;
  whisperCourse?: { label: string } | null;
  currentLocationId?: string;
} | null | undefined): boolean {
  if (!p) return false;
  // #1 fix (indoor prompts on the open road) — mid-journey the player is
  // conceptually walking cross-country, but the departure scene (often a hub
  // room) isn't rebuilt until arrival, so hubRoomId / activeBuildingId linger
  // and the wandering / look-around narration kept emitting interior "you move
  // from room to room" leads out in the open. If a travel course is active —
  // an overland travelTarget pointing at a DIFFERENT location, or any whisper
  // course — the player is ON THE ROAD: never read as indoors. (Mirrors the
  // `onRoute` signal used elsewhere in the store.)
  const onRoad =
    (!!p.travelTarget && p.travelTarget.locationId !== p.currentLocationId) ||
    !!p.whisperCourse;
  if (onRoad) return false;
  return !!p.hubRoomId || !!p.activeBuildingId;
}

function indoorsForOutdoorHooks(get: () => GameStore): boolean {
  const s = get();
  return readsIndoorsForHooks({
    hubRoomId: s.player?.hubRoomId,
    activeBuildingId: s.activeBuildingId,
    travelTarget: s.player?.travelTarget ?? null,
    whisperCourse: s.player?.whisperCourse ?? null,
    currentLocationId: s.player?.currentLocationId,
  });
}

/** arb36 — "you stumble on a structure" line for an enterable building
 *  discovered on a wild tile. Uses the template's article-friendly
 *  hookLabel ("a leaning shack" → "A leaning shack…"). */
// arb120 — the dedicated "ask arbiter" button was dropped as unused; instead the
// Arbiter occasionally seeds the interaction organically by inviting a deeper
// question. The player answers by typing it ("ask the arbiter about the flood",
// "what are the Sentinels", "why did the water come" — all route through the
// `ask` intent), so the prompts read as open doors, not menu items.
const ARBITER_QUESTION_PROMPTS: readonly string[] = [
  `The Arbiter watches the horizon a moment. "Ask me about the flood sometime — why the water rose, and what it left buried."`,
  `The Arbiter trails a hand through the silt. "You could ask me about the Sentinels, if you ever wonder what still walks the deep ruins."`,
  `The Arbiter glances at you sidelong. "Ask me about the Tartarians when you like. It's their world you're walking through."`,
  `The Arbiter is quiet, then: "Ask about the Aether sometime. Most who carry it never learn what it costs them."`,
  `The Arbiter studies a far spire. "Ask me about the Core Guardians before you face one — better to know what waits than meet it blind."`,
  `The Arbiter tilts their head toward you. "You can just ask me things, you know — a faction, a place, a name you half-remember. I keep more than I offer."`,
  `The Arbiter thumbs the edge of an old coin. "Ask me about the factions sometime, if you can't tell whose side the dust is on."`,
];

/** ⚠⚠ OTA-1428 — THE FOUND HALL'S NAME. Owner: *"can we keep a list of multiple
 *  names for this and just have it randomly pull one as we find it?"*
 *
 *  Hashed from the tile, not rolled: a hall keeps the name it was found under
 *  when the player walks out and back in. A fresh roll per entry would rename
 *  the same building on the same tile, which reads as a different one — and
 *  hashing needs nothing stored, so no save migration and no new field.
 *
 *  ⚠ Only buildings with a NON-EMPTY name pool in buildingMaps.ts. The shed has
 *  no painted plan at all; the market has one but no pool, because it is a
 *  single fixed place and rolling a name for it would rename a landmark the
 *  player was told about and routed to. Both fall through to the template's own
 *  name here, which is the pre-OTA-1428 behaviour exactly. */
export function foundBuildingName(buildingId: string, tileKey: string): string {
  return buildingNameFor(buildingId, tileKey) ?? getBuilding(buildingId)?.name ?? 'a structure';
}

function buildingTileKey(get: () => GameStore): string {
  const p = get().player;
  return `${p?.currentLocationId ?? '?'}:${p?.mapX ?? 0}:${p?.mapY ?? 0}`;
}

function buildingApproachLine(buildingId: string, autoTraveling = false, tileKey?: string): string {
  const pooled = tileKey ? buildingNameFor(buildingId, tileKey) : undefined;
  const label = pooled
    ? buildingHookLabel(pooled)
    : getBuilding(buildingId)?.hookLabel ?? 'a structure';
  const Cap = label.charAt(0).toUpperCase() + label.slice(1);
  // arb120 — while auto-travelling the travel row shows STOP, not an ENTER
  // button, so a plain "Tap ENTER" dangles (the player had to discover they
  // could TYPE it). Name the typed path explicitly when on a route.
  const enterHint = autoTraveling
    ? '(You’re on a route — type ENTER to step inside, or keep traveling.)'
    : '(Tap ENTER to step inside.)';
  return `${Cap} stands off the path here — weathered and quiet, a way in still clear. ${enterHint}`;
}

export interface CurrentScene {
  weather: WeatherEntry;
  location: Location;
  hazard: Hazard | null;
  /** All enemies engaged in this scene. Empty when peaceful. */
  enemies: Enemy[];
  /** Current HP per enemy, aligned by index to `enemies`. */
  enemyHps: number[];
  /** Index of the enemy the player is currently targeting. */
  activeEnemyIdx: number;
  vendor: VendorInstance | null;
  /** OTA-1056 — THE PERSON BEHIND THE ENEMY. A vendor who catches you stealing
   *  flips hostile, and OTA-1055's review found the conversion threw them away:
   *  `vendor` was nulled and a generic Enemy installed carrying only a name. So
   *  there was nothing to put back, and nothing to write the consequence
   *  against. VENDORS DO NOT DIE (owner's call — a dead armourer silently
   *  breaks every contract chain that turns in at their counter). They yield.
   *  This is what they are restored from. */
  vendorInFight?: VendorInstance | null;
  /** OTA-451 — a public MISSION BOARD standing in this room (the vendor-free
   *  central square of every faction Outpost). Carries the faction whose
   *  contracts it posts so a new player has an immediate quest on-ramp; the UI
   *  renders a tappable "Mission Board" chip and acceptFactionQuest /
   *  turnInFactionQuest treat it as a quest source (no vendor required). */
  /** ⚠⚠ OTA-1475 — `faction: null` is THE HIDDEN MARKET'S NEUTRAL BOARD, where
   *  every faction posts side by side under the square's truce. Owner: "all of
   *  the factions should be able to post there without interaction from each
   *  other." A named faction is the ordinary outpost board and is unchanged. */
  missionBoard?: { faction: string | null } | null;
  /** OTA-807 — a wandering NPC (a PERSON, not a vendor) resting on this peaceful
   *  outdoor tile. You can talk / greet / persuade them for a small payoff (a tip,
   *  a few coins, or a rare standing nudge). Spawned in beginScene only on NOVEL
   *  ground so it can't be leave/return-farmed; cleared once you've spoken to them.
   *  Null on hubs, markets, combat tiles, and most tiles. */
  wanderer?: import('../engine/wanderers').Wanderer | null;
  /** arb36 — id of an enterable structure standing on the player's current
   *  WILD tile (deterministic via buildingForTile), or null. Surfaces the
   *  ENTER affordance + narration so buildings are discovered organically
   *  while exploring, instead of via the old dev "enter <name>" trigger. */
  sceneBuilding?: string | null;
  /** Distance from the player to the enemy group. Null when peaceful. */
  range: CombatRange | null;
  /** arb168 — set once the player has used (or blown) their one free stealth
   *  OPENER this encounter. After that, sneaking is the initiative-gambit RESET
   *  that costs a turn (the enemy group counters), so the opener can't be
   *  re-triggered every round (the ranged sneak→fire loop). Resets with the
   *  scene (a fresh encounter = a fresh drop). */
  stealthOpenerUsed?: boolean;
  /** OTA-1088 — landed RESISTED hits this fight, keyed `${enemy.name}|${damageType}`.
   *  At GUARD_CRACK_HITS the pair moves to resistCracked and that resist stops
   *  applying. Resets when a fresh enemy lineup replaces the scene's. */
  resistWear?: Record<string, number>;
  /** OTA-1088 — `${enemy.name}|${damageType}` pairs whose guard has been worn
   *  through this fight: damage, narration, and type-procs treat the pair as a
   *  normal matchup from the next swing on. recordEnemyIntel still banks the
   *  TRUE resist, so the bestiary shows the real matchup. */
  resistCracked?: string[];
  /** OTA-913 — set once the sneak-odds warning has fired this encounter (throttle: a
   *  failed close-range sneak warns about the free-hit cost only once per scene). */
  sneakOddsWarned?: boolean;
  /** arb168 — set once a spontaneous investigate-ambush has sprung in this
   *  room. Bounds the farm: a room springs at most ONE ambush per visit, so the
   *  player can't sit on a tile spamming `investigate` to mint free trivial
   *  enemies for stat-training + loot. Resets with the scene (leave + return). */
  investigateAmbushUsed?: boolean;
  /** RETIRED OTA-800 — the wild-drink bound moved off this per-scene flag (which
   *  reset on leave+return, so adjacent outdoor water tiles could be bounced for
   *  infinite drinks) to worldMemory.waterUsedAt, keyed per source on game-hours.
   *  Kept as an optional field so legacy saves that still carry it load cleanly;
   *  no longer read or written. */
  barehandDrinkUsed?: boolean;
  /** RETIRED OTA-800 — see barehandDrinkUsed; the refill bound also moved to
   *  worldMemory.waterUsedAt. Kept optional for legacy-save compatibility. */
  bottleRefillUsed?: boolean;
  /** OTA-796 — dodge-training bound. Successful dodges train DEX/STE only for
   *  the first 3 contest wins per scene visit, so a pet weak enemy can't be
   *  dodge-farmed for unbounded stats. Resets with the scene. */
  dodgeTrainsUsed?: number;
  /** ⚠ OTA-1678 — FAILED breaks against THIS lineup. Each one raises the next
   *  escape bar on random ground (engine/fleeEscalation); never read for a
   *  scripted lineup. Reset by every lineup producer and by FRESH_ENEMY_ARRAYS,
   *  so a count can never outlive the bodies it was earned against. */
  fleeAttempts?: number;
  /** Live narrative hooks the player can follow into multi-stage chains. */
  hooks: Hook[];
  /** Notable nouns extracted from location.description — the things the
   *  scene paragraph mentioned that the player can ask / investigate /
   *  search against. */
  ambientNouns: string[];
  /** A shuffled 5-noun subset of ambientNouns, fixed for this scene
   *  visit. Both look-around AND the chip pool (Search / Approach /
   *  Salvage) read from this exact list — STRICT MATCH: if a noun
   *  isn't in your look, it isn't in your chips either. Hook
   *  primaries are appended on top of chips because they're separate
   *  narrative threads, not ambient props. Set once during
   *  beginScene; leave and come back to re-roll.
   *
   *  Capped at 5 (was 8): a room shouldn't surface 8-10 things to poke
   *  at — that turned INVESTIGATE into a tap-grind (open modal → tap
   *  chip → repeat ~8×) with no "investigate all" to short-circuit it.
   *  Fewer props means fewer taps to clear the green, and since each
   *  investigate keeps the same per-noun find chance, the odds of a
   *  given room showing the player SOMETHING actually hold up. */
  displayedAmbientNouns?: string[];
  /** ⚠⚠ OTA-1244 — NOUNS THAT MUST STAY IN THE DISPLAY WINDOW HOWEVER IT IS
   *  RECOMPUTED. Spawned gear, a water source, a dog-rescue prop: each is placed
   *  deliberately and each was force-prepended at scene build so the 8-slot cap
   *  could not crowd it out.
   *
   *  ⚠ The cardinal-step re-shuffle (OTA-302, 2026-06-05) then replaced
   *  `displayedAmbientNouns` with a blind 8-from-pool pick and re-applied NONE of
   *  them — so gear was guaranteed when you ARRIVED at a location and could vanish
   *  on the next step inside it. Owner: *"I have not seen armor or weapons in the
   *  last few tiles."* Not a drop-rate change and not a bad run: the drop happened,
   *  the display threw it away.
   *
   *  Stamped ONCE at scene build and read by every later recompute, so the
   *  guarantee lives in one place instead of being re-derived (and forgotten) at
   *  each call site. */
  pinnedAmbientNouns?: string[];
  /** ⚠⚠ OTA-1301 — WHICH of the pins are this tile's spawned GEAR.
   *
   *  `pinnedAmbientNouns` merges three unrelated guarantees (spawned gear, the
   *  water source, the dog-rescue prop) into one flat list, and a reader that
   *  needs only one of them has no way to tell them apart. The cardinal-step
   *  path needs exactly that: gear belongs to the TILE and must be left behind
   *  when the player walks off it, while the water source and rescue prop are
   *  location-scoped and must not be. Guessing which is which (e.g. "does the
   *  name resolve to a catalog item?") is the kind of test that passes today and
   *  silently mis-sorts the first time a prop gets a catalog entry — so the
   *  producer records it instead of the consumer inferring it.
   *
   *  Optional: a save written before this OTA has no record, so the first step
   *  after loading drops nothing and the step after that is correct. */
  tileGearNouns?: string[];
  /** OTA-950 — Phase A of real heights: optional per-noun elevation placements
   *  (noun → structure + tier). Absent/empty = everything is on the ground,
   *  which is every scene until the Phase-B seeder ships. */
  nounPlacements?: Record<string, { structure: string; tier: number }>;
  /** OTA-1206 — nouns the Aetheric Torch has marked as actually worth
   *  investigating in THIS scene (✦ on the investigate chips). Stamped by
   *  torch use, computed by engine/arbiterEye.ts against the real payoff
   *  branches. Absent until a torch is spent here; not persisted across
   *  scene rebuilds — the light fades when you move on. */
  arbiterEye?: string[];
  /** When this Location maps to a Macro biome in worldLadder.json, the
   *  scene picks a specific Micro-Micro room to flavor the Arbiter's
   *  narration. Stored here (not regenerated each turn) so a single
   *  visit reads as one consistent room. Null for legacy/unmapped
   *  locations — the LLM context falls back to flat Location text. */
  microMicroId: string | null;
  /** Weather changes rarely mid-fight, so the Arbiter announces the
   *  visibility swing-penalty ("−1 to the swing") ONCE per combat instead
   *  of on every attack. Holds the weather name we last announced for; the
   *  arbiter line is suppressed while it matches the current weather, and
   *  re-fires if the weather actually shifts. Cleared when a fresh combat
   *  begins (so each new fight gets one reminder). */
  weatherSwingAnnounced?: string | null;
  /** arb-fix (playtest) — signature-weapon leave lines already explained THIS scene.
   *  The Order's Hollow Edge carries a long "you can't take it" paragraph; clearing
   *  two enforcers in one scene printed it twice back-to-back. The full reason shows
   *  the first time a given signature weapon is left; later ones in the same scene get
   *  a one-line acknowledgement instead. Keyed by weapon name. */
  signatureWeaponsExplained?: string[];
  /** Slow-weather repositioning progress (Iron Fog etc.). Counts player
   *  advance/retreat actions toward the next range change. Reset to 0
   *  whenever range actually changes, the player switches direction, or
   *  the weather clears. */
  repositionPartial?: number;
  /** Last advance/retreat direction the player committed under slow
   *  weather. Used to detect direction changes so partial progress
   *  doesn't carry from "advance" into a later "retreat". */
  repositionDir?: 'advance' | 'retreat';
  /** OTA-127 — per-step intermediate area label when the player is
   *  in transit (player.travelTarget set, walking between named
   *  locations). The scene's `location.name` reflects the last
   *  named location the player officially entered; while crossing
   *  open ground or unnamed sub-areas, `transitArea` carries the
   *  nearest-named-location label so the scene bar shows "Mud
   *  Flats" while crossing them rather than the stale last-hub
   *  name. Cleared when travel ends or the player officially
   *  enters a new named location. */
  transitArea?: string | null;
  /** OTA-210 — per-enemy status effects (infected, etc.). Parallel
   *  to enemyHps and enemies arrays. Each enemy carries its own
   *  status list; ticks each combat round. Empty array when no
   *  status is active. Initialized empty by beginScene. */
  enemyStatuses?: Array<Array<{
    // engine_Dev (Combat-Parity II) — 'typed_dot' is a generic built-in-damage-type DOT (burn/poison/
    // radiation weapon procs), ticking like the coating DOTs.
    kind: 'infected' | 'poison_coat' | 'acid_coat' | 'corruption_coat' | 'electrical_coat' | 'burn_coat' | 'cold_coat' | 'typed_dot';
    turnsRemaining: number;
    dmgPerTurn: number;
    sourceName: string;
  }>>;
  /** OTA-362 — accumulated acid armor shred per enemy (parallel to
   *  enemies). Each acid-coated hit drops the enemy's AC by
   *  ACID_SHRED_PER_HIT (capped at ACID_SHRED_MAX); buildCombatSteps
   *  reads this via the acReduction opt so subsequent attacks land
   *  more easily. Lazily created on first acid proc. */
  enemyArmorShred?: number[];
  /** ⚠ OTA-1137 — STAGGER, THE REWARD FOR BRINGING THE RIGHT TOOL. Rounds of
   *  stagger remaining per enemy (parallel to `enemies`). A hit that lands on an
   *  enemy's declared WEAKNESS sets this to 1; a boss that is staggered forfeits
   *  its second swing. Lazily created on the first weakness hit, and consumed by
   *  the thing it prevents — see `staggerEnemy` / the boss second-strike block. */
  enemyStaggered?: number[];
  /** ⚠⚠⚠ OTA-1572 — WHAT THE WEAPON DID TO THEM BESIDES DAMAGE. Parallel to
   *  `enemies`. Thirty-three weapons promise a control effect — stun, prone,
   *  restrained, paralyze, slow, blind, knockback — and until this field existed
   *  there was nowhere to put one: every `enemyStatuses` kind is damage-over-
   *  time. One control per enemy, deliberately: two at once is a lock however it
   *  is spelled, so a new one replaces the old rather than stacking beside it.
   *  Lazily created on the first control that lands. See engine/enemyControl. */
  enemyControl?: Array<import('../engine/enemyControl').EnemyControlState | null>;
  /** ⚠⚠⚠ OTA-1572 — THE ANTI-LOCK GUARD, and it is half the feature, not a
   *  follow-up. Rounds of incapacitation-immunity per enemy, mirroring the
   *  player's `braced` (OTA-1089, whose note records 844 stuns/run before it
   *  existed). Sparkstrike is a COMMON rune-caster with an unconditional
   *  1-round stun; without this, one of those ends every single-enemy fight
   *  before the enemy swings once. */
  enemyBraced?: number[];
  /** OTA-362 — accumulated corruption stacks per enemy (parallel to
   *  enemies). Each corruption-coated hit adds a stack; the corruption
   *  DOT ticks harder per stack (coatingDotPerTurn), so tough foes hit
   *  many times rot faster. Lazily created on first corruption proc. */
  enemyCorruptionStacks?: number[];
  /** OTA-361 — per-enemy knockout flag. Parallel to enemyHps /
   *  enemies. Set true when the player lands a single non-lethal blow
   *  dealing ≥ half a HUMANOID enemy's max HP. A knocked-out enemy is
   *  OUT of the fight — it never counter-attacks (runEnemyGroupCounters
   *  skips it) — and is lootable via the combat Loot action, which
   *  transfers its `carries` kit (damaged) + loot + TC and removes it
   *  from the scene. Initialized all-false in beginScene. */
  enemyKnockedOut?: boolean[];
  /** Whether each enemy in `enemies` has already used its
   *  ambush_strike trait this scene. Parallel to enemyHps. Trait
   *  fires only on the first counter; the +2 bonus is consumed and
   *  the flag set true. Initialized empty in beginScene. */
  enemyAmbushUsed?: boolean[];
  /** OTA 031 — what the player is currently elevated on (climbed at
   *  least one tier). Set on every successful climb tier, cleared by
   *  climb down or by leaving the scene. Drives the CLIMB / CLIMB
   *  UP / CLIMB DOWN button toggle in the exploration HUD.
   *  Stored as a tuple so the HUD knows how many tiers are left
   *  (OTA 032 — was a bare string; led to "stuck at tier 1, can
   *  only descend" because the UI couldn't tell the player wasn't
   *  at the top yet). */
  elevatedOn?: {
    noun: string;
    tier: number;
    totalTiers: number;
  } | null;
  /** OTA-960 — set by the timed ambush spawner when the party arrives while the
   *  player is UP a climb: these enemies mass at the BASE, not at your level.
   *  Grounded melee members can't reach you (and you need a weapon that
   *  SHOOTS to reach them); airborne + ranged members fight across the gap.
   *  Wall/summit encounters (spawned at your level) leave this false, so
   *  summit brawls stay ordinary melee. */
  enemiesAtBase?: boolean;
  /** 2026-05-27 OTA-089 — elevated overlay state. When the
   *  player crests a multi-tier climb and the overlay roll
   *  hits, this scene becomes a mini-area (nook / vantage /
   *  roost / collector / sealed-door / open-sky). The
   *  preserved-on-descent reference is the scene the player
   *  WAS in before climbing — `climb down` restores it.
   *  elevatedOverlayMeta carries the climbed noun + room key
   *  + max-tier so the descent can write the cleared marker
   *  back to the original room's searchedAmbientNouns. Both
   *  are undefined for normal scenes. */
  preservedSceneOnDescent?: CurrentScene;
  elevatedOverlayMeta?: {
    climbedNoun: string;
    climbedRoomKey: string;
    maxTier: number;
    overlayId: string;
  };
}

function collectSceneNouns(scene: CurrentScene): string[] {
  // Locations are containers, not interactable targets — never include
  // scene.location.name here. The Location name shouldn't surface as
  // "investigate X" / "use torch on X" since it leads to nonsense
  // suggestions like "use torch on tartarian outskirts." The parser still
  // gets the Location name separately via ParseContext.currentLocationName
  // so it can recognize the name without treating it as a noun.
  const nouns = [scene.weather.name];
  if (scene.hazard) nouns.push(scene.hazard.name);
  for (const e of scene.enemies) {
    nouns.push(e.name, e.type);
    // Phase 4 §2.2 — aliases. Enemies can list synonyms ("sentinel",
    // "guardian", "statue" for an Architectural Sentinel) so the parser
    // matches what the player actually types, not just the canonical
    // name. Empty / missing arrays are safe — the spread is a no-op.
    if (e.aliases) nouns.push(...e.aliases);
  }
  // Ambient nouns from the location description so the parser can resolve
  // "investigate the traps" / "ask about buried cities" against the same
  // content the player just read in the scene paragraph.
  if (scene.ambientNouns) nouns.push(...scene.ambientNouns);
  // Hook nouns so a search hits an active narrative thread.
  if (scene.hooks) {
    for (const h of scene.hooks) {
      if (!h.resolved) nouns.push(...h.nouns);
    }
  }
  // Location aliases — "workroom" / "arch" / "hollow" should resolve to
  // a Tartarian Arch even though we don't pool the canonical Location
  // name itself. The parser uses recentNouns for matchAmbientNoun, so
  // adding the aliases here lets a player type "search the workroom"
  // and have the engine recognize it.
  //
  // ⚠ OTA-1155 — AND THEY GO LAST, WHICH IS THE WHOLE POINT OF MOVING THEM.
  // They used to be pushed BEFORE ambientNouns and hooks. `resolveContextNoun`
  // breaks a substring tie by ARRAY ORDER (parser.ts, `return matches[0]`), so a
  // container's alias beat every authored prop in the room. Device log
  // 2026-08-07T00:30:37: the owner typo'd `climb river-xord` in Ostragar, which
  // has an interactable literally called `river-cord` — and it resolved to
  // `river capital`, an ALIAS OF THE CITY THEY WERE STANDING IN, then narrated
  // the city as an object: "The Arbiter glances at the river capital."
  //
  // ⚠ This is OTA-1149's own bug report, the half it did not fix. That OTA opened
  // with `craft Blue Cap Draught` → "mountain capital" and then repaired only
  // `resolveItem`; `resolveContextNoun` was never touched, and the same shape came
  // back one OTA later. Fixed HERE rather than in the tiebreak because the comment
  // at the top of this function already states the rule — locations are containers,
  // not interactable targets — and pushing their aliases ahead of the real props
  // was simply that rule being broken three lines after it was written. Aliases
  // still resolve when they are the ONLY match, which is all they were ever for.
  if (scene.location?.aliases) nouns.push(...scene.location.aliases);
  // When a vendor is present, the scene has all the trappings of a market
  // even if the location description doesn't spell it out. Add the obvious
  // commerce vocabulary so the player can type "search the market" /
  // "investigate the stall" without getting the soft "I don't see a market
  // here" refusal. Cheap — 8 strings per vendor-bearing scene.
  if (scene.vendor) {
    nouns.push('market', 'stall', 'bazaar', 'shop', 'trader', 'trade', 'wares', 'counter');
  }
  return nouns;
}

export type CognitiveStatus = 'idle' | BootStage | 'failed' | 'skipped';

// ⚠ OTA-1393 — the `cognitive` singleton MOVED to app/ai/engines.ts, a leaf both
// this file and the slices can import. It is referenced 28 times below and could
// not be reached from a slice while it lived here; see engines.ts for why the
// value had to move down rather than be exported sideways.

// Second AI engine — the generative Arbiter narrator. Loaded lazily on demand;
// initialization is slow (~hundreds of MB download on first launch) so we keep
// it on a separate boot path from the MiniLM classifier above. Until it
// reports ready, the narrative pipeline keeps using the existing template
// pools — there is no degraded mode.
// ⚠ OTA-1393 — the `qwen` singleton MOVED to app/ai/engines.ts alongside
// `cognitive`. 73 references below; same reason.

// arb43 — Qwen-backed Arbiter persona answer. When an `ask` isn't a map
// query, a canned introspection line, a structured world-knowledge lookup,
// or a lore-bank hit, the Arbiter answers IN VOICE via Qwen instead of going
// silent — so "why are you following me", "do you know me", "what do you
// want from me", etc. get a real, in-character reply. Guardrails keep him
// from inventing names / counts / events he cannot know. Returns null when
// Qwen isn't ready or returns nothing usable, so the caller can fall back to
// the silent lore line.
const ARBITER_PERSONA_SYSTEM =
  "You are the Arbiter: the old, mysterious witness who walks the buried, " +
  "mud-drowned world of Tartaria beside the traveler. Voice: terse, gruff, " +
  "weathered, a little cryptic — never cheerful, never modern, never chatty. " +
  "Canon you may lean on: you had a name before the flood, but it is buried " +
  "with the city that used it; you do not sleep and do not bleed; you are " +
  "neither god nor ghost nor relic; the buried country appoints witnesses, " +
  "and you are one of them. RULES: reply in 1-3 short sentences, in the " +
  "Arbiter's voice. Do NOT invent proper names of people, places, factions, " +
  "items, or events, and do NOT state counts or facts you are unsure of — if " +
  "asked something you cannot know, say it is buried or does not surface. " +
  "Never mention games, rules, or AI, and never break character.";

/** OTA-1067 — `brief` is Phase 5's ONLY touch on the model path: one sentence
 *  of where he stands in the arc and what he currently thinks of the player,
 *  appended to the fixed system prompt. Additive by design — an empty brief
 *  leaves the prompt byte-identical to what shipped before, and a failed
 *  generation still falls through to the same silent-lore line it always did.
 *  A personality that only exists while a 0.5B model happens to be warm is not
 *  a personality, so everything else in Phase 5 is authored text. */
async function arbiterPersonaAnswer(question: string, brief = ''): Promise<string | null> {
  if (!qwen.isReady()) return null;
  try {
    const out = await qwen.generate(
      [
        { role: 'system', content: brief ? `${ARBITER_PERSONA_SYSTEM} ${brief}` : ARBITER_PERSONA_SYSTEM },
        { role: 'user', content: question },
      ],
      { maxNewTokens: 90, temperature: 0.7, job: 'ask_arbiter' },
    );
    // OTA-494 — sieve foreign words from the Ask-the-Arbiter answer too (same
    // model code-switch risk as the narration feed).
    const line = repairGluedNarration(stripForeignWords((out ?? '').trim()));
    if (line.length === 0) return null;
    // OTA-1595 — the out-of-character sieve (see askArbiter.ts). Null, not a
    // rewrite: the silent line is authored and in voice; a patched leak is not.
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { arbiterAnswerOutOfCharacter } = require('../engine/askArbiter') as typeof import('../engine/askArbiter');
    if (arbiterAnswerOutOfCharacter(line)) return null;
    return line;
  } catch {
    return null;
  }
}

// arb45 — Arbiter title-earning plumbing. `recordTitleProgress` bumps the
// player's title counters (and folds in max-value fields like maxCorruption),
// then `awardNewTitles` re-evaluates ALL 14 wired Tier-A/B predicates and
// awards any newly-satisfied title with an in-voice Arbiter line. Because the
// evaluation is holistic, the derived titles (golem/scion/explorer/aetherborn)
// are caught by the periodic catch-all call in the world tick — no per-site
// wiring needed for those.
const ARBITER_TITLE_META: Record<string, { title: string; perk: string }> = (() => {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const data = require('../data/lore/arbiter-titles.json') as { titles: Array<{ id: string; title: string; perk: string }> };
  const m: Record<string, { title: string; perk: string }> = {};
  for (const t of data.titles) m[t.id] = { title: t.title, perk: t.perk };
  return m;
})();

function awardNewTitles(getStore: () => GameStore, setStore: (u: Partial<GameStore> | ((s: GameStore) => Partial<GameStore> | GameStore)) => void): void {
  const player = getStore().player;
  if (!player) return;
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { newlyEarnedTitles, TITLE_PASSIVE_PERK } = require('../engine/titles');
  // arb-fix — SPAM + persistence guard. Storm titles (Etherbound Survivor /
  // Aetheric Attuned / Stormcaller) are awarded MID-action from the weather tick,
  // and later stale-`player` writebacks in the same action revert earnedTitles /
  // titleProgress — so the perk never stuck and the "You have earned a name to
  // carry" banner re-fired on every fog tick. worldMemory.earnedTitleAnnounced is
  // an announce-once ledger that player writebacks don't clobber. Because this
  // runs at the pre-snapshot catch-all every action, step (a) folds any ledgered
  // title back into earnedTitles so the perk PERSISTS, and step (b) announces a
  // title only the first time it is earned.
  const announced: string[] = getStore().worldMemory?.earnedTitleAnnounced ?? [];
  // (a) reconcile — earnedTitles must contain everything already announced.
  const clobbered = announced.filter((id) => !(player.earnedTitles ?? []).includes(id));
  if (clobbered.length > 0) {
    setStore((s) => (s.player
      ? { player: { ...s.player, earnedTitles: [...(s.player.earnedTitles ?? []), ...clobbered] } }
      : s));
  }
  const p2 = getStore().player;
  if (!p2) return;
  const fresh: string[] = newlyEarnedTitles(p2);
  if (fresh.length === 0) return;
  // OTA-848 — stamp each freshly-earned title with WHEN it landed (in-game hour
  // + real time) so the Character screen can show its earn-date on tap.
  const atHours = p2.hoursElapsed ?? 0;
  const atMs = Date.now();
  const freshLog = fresh.map((id) => ({ id, atHours, atMs }));
  setStore((s) => (s.player
    ? { player: {
        ...s.player,
        earnedTitles: [...(s.player.earnedTitles ?? []), ...fresh],
        titleLog: [...(s.player.titleLog ?? []), ...freshLog],
      } }
    : s));
  // (b) announce only titles never announced before, and record them in the
  // clobber-immune ledger so a later revert can't make them re-fire.
  const toAnnounce = fresh.filter((id) => !announced.includes(id));
  if (toAnnounce.length > 0) {
    setStore((s) => ({ worldMemory: { ...s.worldMemory, earnedTitleAnnounced: [...announced, ...toAnnounce] } }));
  }
  // ⚠ OTA-1093 — ONE NAME AT A TIME. Two titles landing in the same beat gave
  // the owner back-to-back "You have earned a name to carry" banners mid-fight
  // (Aetherbound Survivor + Stormcaller, device log 2026-08-04) — the same
  // pile-up OTA-1036 fixed for reward lines. A title is a moment; two moments
  // stacked read as one long block of text nobody parses. The first is spoken
  // now with its full honest perk; the rest are folded into one following line
  // that NAMES them, so nothing is hidden — it just stops shouting.
  // Keep the id alongside the meta — the honest-perk lookup below is keyed by
  // id, and a `.filter(Boolean)` does not narrow the meta type on its own.
  const spoken = toAnnounce
    .map((id) => ({ id, meta: ARBITER_TITLE_META[id] }))
    .filter((e): e is { id: string; meta: NonNullable<typeof e.meta> } => !!e.meta);
  const first = spoken[0];
  if (first) {
    const firstId = first.id;
    // OTA-353 — announce the HONEST passive effect, not the canon
    // arbiter-titles.json "Once per day…" flavor. The engine implements these
    // as always-on passives (and several now grant +Stealth, OTA-350); the
    // earn message used to promise a daily active that doesn't exist. The
    // Character screen already shows TITLE_PASSIVE_PERK — match it here.
    const honest: string = (TITLE_PASSIVE_PERK as Record<string, string>)[firstId] ?? first.meta.perk;
    getStore().appendLog(
      'arbiter',
      `The Arbiter studies you a long moment. "You have earned a name to carry: ${first.meta.title}. ${honest}"`,
    );
    const rest = spoken.slice(1);
    if (rest.length > 0) {
      getStore().appendLog(
        'arbiter',
        rest.length === 1
          ? `"And a second, in the same breath: ${rest[0]!.meta.title}. Read them on your sheet when the dust settles."`
          : `"And ${rest.length} more in the same breath: ${rest.map((m) => m.meta.title).join(', ')}. Read them on your sheet when the dust settles."`,
      );
    }
  }
}

export function recordTitleProgress(
  getStore: () => GameStore,
  setStore: (u: Partial<GameStore> | ((s: GameStore) => Partial<GameStore> | GameStore)) => void,
  delta?: Record<string, number>,
  maxes?: Record<string, number>,
): void {
  const player = getStore().player;
  if (!player) return;
  // OTA-1046 — NOTHING IN THE TUTORIAL COUNTS. The tutorial is a scripted
  // sandbox: it hands you a cudgel, a rope and a rigged four-tier climb. A
  // legend should not be able to start there. Owner report: two titles landed
  // mid-tutorial off a single line of ambient black rain, before the scripted
  // climb was even finished.
  // Progress is not merely un-awarded here, it is not RECORDED -- otherwise the
  // player banks counters through the sandbox and collects the titles the
  // instant the tutorial ends, which reads exactly as unearned.
  const tState = getStore();
  if (tState.tutorialStep !== null && !tState.tutorialExploreChosen) return;
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { withTitleProgress } = require('../engine/titles');
  const next = withTitleProgress(player.titleProgress);
  const n = next as unknown as Record<string, number>;
  if (delta) for (const k of Object.keys(delta)) n[k] = (n[k] ?? 0) + (delta[k] ?? 0);
  if (maxes) for (const k of Object.keys(maxes)) n[k] = Math.max(n[k] ?? 0, maxes[k] ?? 0);
  setStore((s) => (s.player ? { player: { ...s.player, titleProgress: next } } : s));
  awardNewTitles(getStore, setStore);
}

// OTA-912 — Skyreacher Charts: the five maps that UNLOCK the great climbs. Sold
// only by roadside traders, each chart exactly ONCE ever (worldMemory.soldMapIds),
// and never a chart for a climb already unlocked. climbId matches a GREAT_CLIMBS id.
// Exported for the OTA-912 full-run verification test.
export const SKYREACHER_CHARTS: readonly { name: string; climbId: string; price: number }[] = [
  { name: 'Skyreacher Map 1 of 5 — Grand Spire',       climbId: 'grand_spire',       price: 110 },
  { name: 'Skyreacher Map 2 of 5 — Asgardar Spire',    climbId: 'asgardar_spire',    price: 100 },
  { name: 'Skyreacher Map 3 of 5 — Obsidian Monolith', climbId: 'obsidian_monolith', price: 95 },
  { name: 'Skyreacher Map 4 of 5 — Thametan Tower',    climbId: 'thametan_tower',    price: 90 },
  { name: 'Skyreacher Map 5 of 5 — Zharak Fang',       climbId: 'zharak_fang',       price: 85 },
];
/** Names of the five charts — used by the buy path to stamp soldMapIds. */
export const SKYREACHER_CHART_NAMES: ReadonlySet<string> = new Set(SKYREACHER_CHARTS.map((c) => c.name));
// OTA-968 — the maps were named 'Skyreacher Chart (N of 5)' before this build
// (owner: "it's not a chart. we should call it a map" — and the name should say
// where it leads). Old saves still carry the chart names in inventories and in
// the sell-once ledger (soldMapIds stores NAMES): backfillPlayer renames held
// items on load, and the roadside offer filter treats a legacy ledger entry as
// sold. Index i here pairs with SKYREACHER_CHARTS[i].
export const LEGACY_SKYREACHER_CHART_NAMES: readonly string[] =
  [1, 2, 3, 4, 5].map((n) => `Skyreacher Chart (${n} of 5)`);

/** OTA-912 — the shared "use a Skyreacher Chart" effect: unlock the great climb
 *  (so its prop spawns at the landmark), reveal + log the landmark, and consume
 *  one chart. Called from BOTH the inventory USE button (useInventoryItem) and
 *  the typed `use` verb, so it doesn't depend on the parser resolving the chart's
 *  parenthesised name. Returns true if it handled the item. */
export function unlockGreatClimbFromChart(
  getStore: () => GameStore,
  setStore: (u: Partial<GameStore> | ((s: GameStore) => Partial<GameStore> | GameStore)) => void,
  item: { id: string; name: string },
  climbId: string,
): boolean {
  const player = getStore().player;
  if (!player) return false;
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { greatClimbById } = require('../engine/greatClimbs');
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { discoverLocation } = require('../engine/worldMemory');
  const gc = greatClimbById(climbId);
  if (!gc) {
    getStore().appendLog('world', `The ${item.name} is too weather-worn to make out. Nothing comes of it.`);
    return true;
  }
  const already = (getStore().worldMemory.unlockedGreatClimbs ?? []).includes(gc.id);
  // Consume one chart — spent fixing the route.
  setStore((s) => (s.player
    ? { player: { ...s.player, inventory: s.player.inventory
        .map((i) => (i.id === item.id ? { ...i, quantity: i.quantity - 1 } : i))
        .filter((i) => i.quantity > 0) } }
    : s));
  setStore((s) => ({
    worldMemory: {
      ...discoverLocation(s.worldMemory, gc.locationId),
      unlockedGreatClimbs: Array.from(new Set([...(s.worldMemory.unlockedGreatClimbs ?? []), gc.id])),
    },
  }));
  getStore().appendLog(
    'world',
    already
      ? `You spread the ${item.name} again. ${theCap(gc.noun)} is already fixed on your route.`
      : `You unroll the ${item.name} and trace the giant-drawn lines. ${theCap(gc.noun)} settles onto your atlas — the great climb is open, and a new charge stands on your board. Travel there, bring the Hardened Climbing Strap and a whole Reclaimer's Rope, and make the ascent.`,
  );
  if (!already) {
    // OTA-968 — say plainly what just happened (owner: "a text pops up saying that
    // you've added the skyreacher location ... to the map and mission logs").
    getStore().appendLog('reward', `✦ Skyreacher location added to your MAP and MISSION LOG — ${theCap(gc.noun)}.`);
    getStore().appendLog(
      'arbiter',
      `"A collector tower," the Arbiter murmurs. "One of the sky-antennas that drank the heavens dry. Its guardian still holds the crown. Climb into the heart of it, ${player.name}, if you mean to."`,
    );
  }
  void getStore().persist();
  return true;
}

/** OTA-913 — build the Beacon Rifle by breaking down the Aether Collection
 *  Beacons. Triggered by USING a beacon once all five towers are cleared: the
 *  collector-arrays are re-purposed into a rifle that pulls charge from the air
 *  and throws it (electrical + a permanent acid rider). One-time. Returns true
 *  when it handled the use (always, once resolved to a beacon). */
export function assembleBeaconRifle(
  getStore: () => GameStore,
  setStore: (u: Partial<GameStore> | ((s: GameStore) => Partial<GameStore> | GameStore)) => void,
): boolean {
  const player = getStore().player;
  if (!player) return false;
  const wm = getStore().worldMemory;
  if (wm.skyreacherBoltcasterGranted) {
    getStore().appendLog('world', `The arrays are already spent — the Beacon Rifle is built. This node is an empty shell now.`);
    return true;
  }
  const bossesDown = (wm.summitBossesDefeated ?? []).length;
  const heldBeacons = player.inventory
    .filter((i) => i.name === 'Aether Collection Beacon')
    .reduce((s, i) => s + i.quantity, 0);
  if (bossesDown < 5 || heldBeacons < 5) {
    getStore().appendLog(
      'world',
      `A single collector-node hums in your hand, its needle swinging toward the sky. On its own it does nothing — you'd need all five, one carried down from each great climb, before there's anything to build.`,
    );
    return true;
  }
  const rifle: InventoryItem = stampDurability({
    id: freshInstanceId('beacon_rifle'), name: 'Beacon Rifle', kind: 'weapon', rarity: 'Legendary',
    quantity: 1, tags: ['weapon', 'ranged', 'beacon_rifle', 'skyreacher', 'legendary', 'collect_only'],
    // electrical (catalog) + a permanent acid rider → electrical AND acid at once.
    coating: { kind: 'acid', dice: '2d6', label: 'Acid' },
  });
  const mats: InventoryItem[] = [
    { id: freshInstanceId('mat'), name: 'Throne Shard', kind: 'misc', rarity: 'Legendary', quantity: 2, tags: ['material', 'legendary'] },
    { id: freshInstanceId('mat'), name: 'Iron Core', kind: 'misc', rarity: 'Legendary', quantity: 2, tags: ['material', 'legendary'] },
    { id: freshInstanceId('mat'), name: 'Aether Shard', kind: 'misc', rarity: 'Rare', quantity: 3, tags: ['material', 'rare'] },
  ];
  setStore((s) => {
    if (!s.player) return s;
    let inv = s.player.inventory;
    let toConsume = 5; // disassemble the five collector-arrays
    inv = inv.map((i) => {
      if (i.name === 'Aether Collection Beacon' && toConsume > 0) {
        const take = Math.min(i.quantity, toConsume); toConsume -= take;
        return { ...i, quantity: i.quantity - take };
      }
      return i;
    }).filter((i) => i.quantity > 0);
    inv = mergeOrPushItem(inv, rifle);
    for (const m of mats) inv = mergeOrPushItem(inv, m);
    return { player: { ...s.player, inventory: inv }, worldMemory: { ...s.worldMemory, skyreacherBoltcasterGranted: true } };
  });
  getStore().appendLog(
    'world',
    `You crack the five beacons open across your knees and read how they were made: each is a folded collector-array — a throat of resonant crystal built to swallow Aether out of thin air and push it on down the grid. You strip the arrays, splice the five throats into a single barrel, and re-wire the intake to fire instead of feed. It takes the better part of a day. When you seat the last crystal the whole thing wakes with a shriek of live current: a rifle that grabs charge from an empty sky and throws it.`,
  );
  getStore().appendLog('reward', `✦✦ BEACON RIFLE (Legendary) — built from the five collector-arrays. Fires an electrical bolt sheathed in acid, the two elements every Tartarian machine dreads. With it, a cache of legendary materials.`);
  getStore().appendLog('arbiter', `"You climbed into the heart of every tower that drowned the world," the Arbiter says quietly, "and made the thing that drank the sky spit it back out. Nothing built will stand easy in front of that."`);
  // OTA-1037 — AND IT GETS A CARD. The doubled ✦✦ above was the only thing
  // marking this as bigger than a Trail Rations pickup, and a feed line is
  // exactly what OTA-1010 was written because the player scrolls past — the
  // owner's words then were "I didn't even realize I completed the mission."
  // This is the payoff for all five great climbs: a Legendary weapon plus seven
  // Legendary/Rare materials, and it announced itself the same way a mud cloth
  // does. The boss VICTORY card already knew how to show story-then-take, so it
  // is reused under its own banner. The feed lines above are UNCHANGED — the log
  // stays a complete record, same rule as every other announcement.
  getStore().raiseSpotlightNotice(
    'BEACON RIFLE ASSEMBLED',
    'Beacon Rifle (Legendary)',
    [
      `You crack the five beacons open across your knees: each is a folded collector-array, a throat of resonant crystal built to swallow Aether out of thin air. You splice the five throats into a single barrel and re-wire the intake to fire instead of feed. When you seat the last crystal the whole thing wakes with a shriek of live current.`,
      `"You climbed into the heart of every tower that drowned the world," the Arbiter says quietly, "and made the thing that drank the sky spit it back out. Nothing built will stand easy in front of that."`,
    ],
    [
      `Beacon Rifle (Legendary) — electrical bolt sheathed in acid, the two elements every Tartarian machine dreads.`,
      ...mats.map((m) => `${m.name} ×${m.quantity} (${m.rarity})`),
    ],
  );
  void getStore().persist();
  return true;
}

/** ~18% of eligible roadside stalls carry one not-yet-sold, not-yet-unlocked
 *  chart. Returns the vendor (possibly) augmented with a single chart offer.
 *  Exported for the OTA-912 full-run verification test. */
export function withSkyreacherChartOffer(vendor: VendorInstance | null, wm: WorldMemory): VendorInstance | null {
  if (!vendor || !vendor.id.startsWith('roadside_')) return vendor; // roadside traders only
  if (Math.random() >= 0.18) return vendor;
  const sold = wm.soldMapIds ?? [];
  const unlocked = wm.unlockedGreatClimbs ?? [];
  const already = new Set(vendor.offers.map((o) => o.itemName));
  const pick = SKYREACHER_CHARTS.find(
    // OTA-968 — a pre-rename sale wrote the old 'Skyreacher Chart (N of 5)' name
    // into the ledger; that map is still sold-once, never offered again.
    (c, i) => !sold.includes(c.name) && !sold.includes(LEGACY_SKYREACHER_CHART_NAMES[i]!)
      && !unlocked.includes(c.climbId) && !already.has(c.name),
  );
  if (!pick) return vendor;
  return { ...vendor, offers: [...vendor.offers, { itemName: pick.name, price: pick.price, quantity: 1 }] };
}

/** ⚠ OTA-1195 — THE ONE WAY INTO AETHER TECHNIQUES (PUNCHLIST P16). Owner: *"buy from
 *  friendly vendors you developed repor with."*
 *
 *  Modelled on `withSkyreacherChartOffer` directly above — same shape, same place in
 *  `beginScene`, same "append one conditional row" contract — with one deliberate
 *  difference: **there is no die roll.** A chart is a bonus you may or may not stumble on;
 *  this is the ONLY route into a whole feature, and a route that appears 18% of the time
 *  is indistinguishable from a route that does not exist. A faction's vendors always carry
 *  that faction's procedure, so a player can go and get it.
 *
 *  The gates live in `techniqueTextOfferFor` so they can be tested without a store. */
export function withTechniqueTextOffer(
  vendor: VendorInstance | null,
  player: PlayerCharacter | null,
): VendorInstance | null {
  if (!vendor || !player) return vendor;
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const AT = require('../engine/aetherTechniques') as typeof import('../engine/aetherTechniques');
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { hasFactionRapport } = require('../engine/factionRapport') as typeof import('../engine/factionRapport');
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { effectiveStats } = require('../engine/equipment') as typeof import('../engine/equipment');
  // ⚠ nativeFaction first: OTA-1186 skins a site to its OWNER, and the Irma path rewrites
  // `faction` to the visitor's. The procedure belongs to whoever the vendor really answers
  // for, or a Mud Monarch would be sold the Architects' text by an Architect wearing his
  // colours.
  const faction = vendor.nativeFaction ?? vendor.faction;
  const offer = AT.techniqueTextOfferFor({
    vendorFaction: faction,
    hasRapport: hasFactionRapport(player.completedFactionQuestIds, faction),
    knownTechniques: player.knownTechniques,
    effectiveInt: effectiveStats(player).intelligence,
  });
  if (!offer) return vendor;
  if (vendor.offers.some((o) => o.itemName === offer.itemName)) return vendor;
  return { ...vendor, offers: [...vendor.offers, offer] };
}

// arb48 — Labyrinth of Shadows (Wayfarer of the Lost Paths). Both helpers are
// store-driving wrappers around the pure engine in engine/labyrinth.ts.
type StoreGet = () => GameStore;
type StoreSet = (u: Partial<GameStore> | ((s: GameStore) => Partial<GameStore> | GameStore)) => void;

function enterLabyrinth(getStore: StoreGet, setStore: StoreSet): void {
  const player = getStore().player;
  if (!player) return;
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const lab = require('../engine/labyrinth');
  const run = lab.startRun();
  setStore((s) => (s.player ? { player: { ...s.player, labyrinthRun: run } } : s));
  getStore().appendLog('world', 'You step into the Labyrinth of Shadows. False doors and overlaid corridors fold the dark around you — every map of this place is wrong by design. The heart lies somewhere to the north and east.');
  getStore().appendLog('arbiter', `"Trust the true path, ${player.name}, not your eyes. Stray too often and the maze keeps you."`);
  getStore().appendLog('world', `Passages lead: ${lab.openDirections(run.pos).map(lab.dirWord).join(', ')}. (Type a direction — north / east / south / west — or LEAVE to step back out.)`);
}

/** Handles every input while a maze run is active. Returns true (it always
 *  consumes the turn) so the caller can early-return. */
function handleLabyrinthStep(getStore: StoreGet, setStore: StoreSet, trimmed: string): boolean {
  const player = getStore().player;
  const run = player?.labyrinthRun;
  if (!player || !run) return false;
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const lab = require('../engine/labyrinth');
  const openLine = (open: string[]) => open.map(lab.dirWord).join(', ');

  if (/^\s*(leave|exit|out|step\s+out|give\s+up|abandon|back\s+out|stop)\s*$/i.test(trimmed)) {
    setStore((s) => (s.player ? { player: { ...s.player, labyrinthRun: undefined } } : s));
    getStore().appendLog('world', 'You retrace your steps to the mouth of the maze and step back out into Iskan-Veil.');
    return true;
  }
  const dir = lab.parseDir(trimmed);
  if (!dir) {
    getStore().appendLog('world', `Inside the maze you can only move. Passages lead: ${openLine(lab.openDirections(run.pos))}. Type a direction, or LEAVE.`);
    return true;
  }
  const res = lab.step(run, dir);
  if (res.blocked) {
    getStore().appendLog('world', `A false wall — the corridor doesn't run ${lab.dirWord(dir).toLowerCase()}. Passages lead: ${openLine(res.open)}.`);
    return true;
  }
  setStore((s) => (s.player ? { player: { ...s.player, labyrinthRun: res.run } } : s));
  if (res.reachedFinish) {
    const clean = lab.isCleanRun(res.run);
    setStore((s) => (s.player ? { player: { ...s.player, labyrinthRun: undefined } } : s));

    // ⚠⚠ OTA-1190 (PUNCHLIST P13) — THE MAZE HAS AN ENDING NOW.
    //
    // What it was: a clean run printed one line and ticked the Wayfarer counter; **any
    // other run printed two lines and nothing else** — no TC, no item, no progress — and
    // the run object was discarded. A maze walked with one wrong turn paid exactly what a
    // maze walked with nine paid. That is an ENDS IN NOTHING on a challenge P5 confirmed
    // is live, and the owner's call was: *"we need an ending to p13 the labyrinth. it
    // should already award a title, make it have a lore enriching ending."*
    //
    // ⚠ THE LORE IS THE PAYOUT, and it was sitting in the data the whole time.
    // `locations.json` on Iskan-Veil: *"The Conspiracy Architects' hidden city — a maze of
    // false doors and overlaid corridors. Every map of Iskan-Veil is wrong by design; the
    // true Core seat is behind the door you didn't see."* And `concepts.json` names its
    // Core's function among the nine: **masking.** So the reveal at the heart is not a
    // consolation prize bolted on — it is the answer to what this place IS. The labyrinth
    // is not a puzzle guarding the Core. **The labyrinth is the Core still working.**
    //
    // ⚠⚠ ONCE PER CHARACTER, AND THAT IS LOAD-BEARING. `enterLabyrinth` carries no attempt
    // gate — the maze is fully re-enterable — so a per-run reward would be farmable, and
    // the fix for an ends-in-nothing must not become a farm. The reveal and its keepsake
    // are gated on `labyrinthHeartSeen`; the Wayfarer counter is unaffected because its
    // threshold is >= 1, so re-earning it is already a no-op.
    const heartSeen = !!getStore().player?.labyrinthHeartSeen;
    if (clean) {
      getStore().appendLog('world', "The corridors open onto a still chamber at the maze's heart. You walked it clean — the true path never left your hands.");
      recordTitleProgress(getStore, setStore, { labyrinthCleanRuns: 1 });
    } else {
      const n = res.run.wrongTurns;
      getStore().appendLog('world', `You reach the heart of the maze — but you strayed ${n} time${n === 1 ? '' : 's'} onto false paths along the way.`);
    }

    if (!heartSeen) {
      // ⚠ Three beats, not one wall of text: AdventureFeed renders separate entries as
      // real paragraphs, and this is the largest single piece of lore the challenge holds.
      getStore().appendLog('world',
        'The chamber is small, and perfectly plain. No door but the one you came through. '
        + 'No seat, no Core, no Guardian — a floor of dressed stone and a low ring of benches, '
        + 'as though the Architects meant people to sit here and wait for something.');
      getStore().appendLog('world',
        'On the wall opposite, cut shallow and without ceremony: a map of the labyrinth. '
        + 'You have just walked it, so you know at a glance that it is wrong. Not damaged, '
        + 'not old — WRONG, corridor for corridor, every turn mirrored from the one you took. '
        + 'Someone carved a lie here carefully enough to be mistaken for a courtesy.');
      getStore().appendLog('arbiter',
        '"Iskan-Veil masked the grid," the Arbiter says quietly. "Nine Cores, nine tasks — '
        + 'Asgardar held the spire, Ostragar the cadence, and this place hid the rest. That '
        + 'was its work." A pause. "You were told the maze guards the Core seat. It does not. '
        + 'The maze IS the Core seat, still running, still masking, a thousand years after '
        + 'the water. Every map of this city is wrong because something down here is still '
        + 'making them wrong. You did not solve it. You outlasted one of its lies."');

      // ⚠ A keepsake, not a reward roll. Quest-tagged so it can never be sold, gifted,
      // scrapped or fused (engine/questItems.ts) — the point is that the player keeps the
      // thing that proves the map lied, not that they can pawn it.
      const rubbing: InventoryItem = {
        id: freshInstanceId('labyrinth_heart'),
        name: 'Rubbing of the False Map',
        kind: 'relic',
        rarity: 'Legendary',
        quantity: 1,
        tags: ['quest', 'story', 'keepsake', 'lore'],
        description:
          "Charcoal on hide, taken from the wall at the heart of the Labyrinth of Shadows. "
          + "It shows the maze mirrored — every turn the wrong way round. Iskan-Veil's Core "
          + "masked the Tartarian grid, and it has never stopped: this is what it is still "
          + "producing, patiently, for nobody. Proof that the lie is maintained.",
      };
      const grant = grantItem(getStore().player!.inventory, rubbing);
      setStore((st) => (st.player ? { player: {
        ...st.player,
        inventory: grant.inventory,
        labyrinthHeartSeen: true,
      } } : st));
      if (grant.accepted > 0) {
        getStore().appendLog('reward', `✦ ${rubbing.name} — you take a rubbing before you leave.`);
      } else {
        // ⚠ A full pack must not silently eat the one artifact of the ending. The flag is
        // still set (the lore was delivered and should not repeat), so this says plainly
        // that the item was lost rather than leaving the player to notice its absence.
        getStore().appendLog('world',
          `Your pack is full — there is nowhere to put the rubbing, and you leave it on the wall.`);
      }
      recordMemorableEvent(getStore, setStore, {
        kind: 'labyrinth_heart',
        text: 'stood at the heart of the Labyrinth of Shadows and read the false map',
        locationId: 'iskan_veil',
        locationName: 'Iskan-Veil',
      });
    } else {
      getStore().appendLog('world',
        'The still chamber again, and the false map on its wall — mirrored, patient, wrong. '
        + 'Whatever is making it has not tired.');
    }

    // ⚠ The steer toward a clean run comes AFTER the ending, so an imperfect first walk
    // reads as "you learned something, now go do it properly" rather than as a refusal.
    if (!clean) {
      getStore().appendLog('arbiter', '"You found the center, not the path. The Wayfarer\'s name is for those who never lose it. Walk it again — cleaner."');
    }
    return true;
  }
  if (res.deadEnd) {
    getStore().appendLog('world', `Dead end — the corridor stops at a blank wall. This was never the way. Passages lead: ${openLine(res.open)}.`);
  } else if (res.enteredBranch) {
    getStore().appendLog('world', `The passage narrows and the air sours — this feels wrong. Passages lead: ${openLine(res.open)}.`);
  } else {
    getStore().appendLog('world', `You follow the corridor ${lab.dirWord(dir).toLowerCase()}. Passages lead: ${openLine(res.open)}.`);
  }
  return true;
}

// arb50 — content-review Tier-C trials (Speaker @ Red Tower, Warden @ Sinking
// Cathedral). SCOUTING is free + informative; ATTEMPTING is one-shot. Lacking
// the required material refuses the attempt WITHOUT consuming it. `def` is the
// already-matched TitleChallengeDef for the player's current location.
function handleTitleChallenge(getStore: StoreGet, setStore: StoreSet, trimmed: string, def: any): void {
  const player = getStore().player;
  if (!player) return;
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const tc = require('../engine/titleChallenges');
  const req = def.requirement;
  const countOf = (name: string) =>
    player.inventory.filter((i) => i.name === name).reduce((s, i) => s + (i.quantity ?? 1), 0);
  const intVal = effectiveStats(player)[def.check.stat as 'intelligence'] ?? 0;
  const reqLine = `${req.quantity > 1 ? `${req.quantity}× ` : ''}${req.itemName}`;
  const isAttempt = def.attemptVerb.test(trimmed);

  // ── SCOUT (free) ──────────────────────────────────────────────────────────
  if (!isAttempt) {
    let have = countOf(req.itemName);
    if (req.recoverOnScout && have < req.quantity) {
      const res = grantItem(player.inventory, {
        id: freshInstanceId(req.itemName.toLowerCase().replace(/[^a-z0-9]+/g, '_')),
        name: req.itemName, kind: 'misc', quantity: req.quantity, tags: ['quest', 'challenge'],
        description: 'A cryptic device for deciphering Tartarian runes.',
      });
      setStore((s) => (s.player ? { player: { ...s.player, inventory: res.inventory } } : s));
      have = req.quantity;
      getStore().appendLog('reward', `✦ ${req.itemName} (Uncommon).`);
    }
    const status = getStore().player?.challengeAttempts?.[def.id];
    if (status === 'succeeded') { getStore().appendLog('world', `You have already mastered this — the title is yours.`); return; }
    if (status === 'failed') { getStore().appendLog('world', `Your one attempt here is spent.`); return; }
    const haveLine = req.quantity === 0
      ? 'No supplies to gather — this trial asks only what you are.'
      : have >= req.quantity
        ? `You have what you need (${reqLine}).`
        : `You still need ${req.hint}.`;
    getStore().appendLog(
      'world',
      `${haveLine} The trial is ${def.check.trialLabel}: a single d20 + ${def.check.statLabel} (yours: ${intVal}) against DC ${def.check.dc}. ` +
      `${have >= req.quantity ? `Attempt it when ready — you get one chance.` : `Come back when you have it.`}`,
    );
    return;
  }

  // ── ATTEMPT (one-shot) ────────────────────────────────────────────────────
  const status = player.challengeAttempts?.[def.id];
  if (status === 'succeeded') { getStore().appendLog('world', `You've already earned this title — nothing more to prove here.`); return; }
  if (status === 'failed') { getStore().appendLog('world', `You had your one attempt, and it's spent. This trial gives no second chance.`); return; }
  const have = countOf(req.itemName);
  if (have < req.quantity) {
    // refuse WITHOUT consuming the attempt
    getStore().appendLog('world', `You can't make the attempt yet — you need ${req.hint}. (Your one attempt is untouched; return when you're ready.)`);
    return;
  }
  // Commit. Consume materials if required.
  let inv = player.inventory;
  if (req.consumeOnAttempt) {
    let toRemove = req.quantity;
    inv = inv
      .map((it) => {
        if (it.name !== req.itemName || toRemove <= 0) return it;
        const take = Math.min(it.quantity ?? 1, toRemove);
        toRemove -= take;
        return { ...it, quantity: (it.quantity ?? 1) - take };
      })
      .filter((it) => (it.quantity ?? 1) > 0);
  }
  const r = tc.rollCheck(intVal, def.check.dc);
  const attempts = { ...(player.challengeAttempts ?? {}), [def.id]: r.success ? 'succeeded' : 'failed' };
  setStore((s) => (s.player ? { player: { ...s.player, inventory: inv, challengeAttempts: attempts } } : s));
  const rollLine = `(d20 ${r.roll} + ${def.check.statLabel} ${intVal} = ${r.total} vs DC ${r.dc})`;
  if (r.success) {
    if (def.successLine) {
      getStore().appendLog('world', `${def.successLine} ${rollLine}`);
    } else if (def.id === 'tongue_of_the_red_tower') {
      getStore().appendLog('world', `The glyphs resolve under the Glyph-Key's tongue — meaning pours in. You can read the dead language now. ${rollLine}`);
    } else {
      getStore().appendLog('world', `The braces hold. The nave groans, settles, and stands. You've kept a piece of the old world from the dark. ${rollLine}`);
    }
    recordTitleProgress(getStore, setStore, { [def.counter]: 1 });
  } else {
    if (def.failLine) {
      getStore().appendLog('world', `${def.failLine} ${rollLine}`);
    } else if (def.id === 'tongue_of_the_red_tower') {
      getStore().appendLog('world', `The glyphs blur and scatter; the reading collapses into noise. ${rollLine}`);
    } else {
      getStore().appendLog('world', `The braces buckle. A section of the nave caves in with a roar of stone — the shoring is wasted. ${rollLine}`);
    }
    getStore().appendLog('arbiter', `"One chance, and it's gone. Some trials don't forgive."`);
  }
}

// arb55 — Trap Dives of the Endless Stair (Shadow Diver). Unlike the one-shot
// title trials this is a RETRYABLE DEX gauntlet: each dive is a single d20 + DEX
// vs DC 13. A CLEAN dive (pass) banks one of the three you need — trapCleanDives
// accumulates persistently on the player, so the three can be earned across
// separate visits. A tripped trap (fail) springs for 1d6 (never lethal — the
// stair lets you try again) and banks nothing. Scouting is free and reports the
// DC + clean dives banked. At three clean dives recordTitleProgress awards
// Shadow Diver. `isDive` = the player committed a dive; otherwise it's a scout.
function handleTrapDive(getStore: StoreGet, setStore: StoreSet, isDive: boolean): void {
  const player = getStore().player;
  if (!player) return;
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const tc = require('../engine/titleChallenges');
  const dex = effectiveStats(player).dexterity ?? 0;
  const dc = 13;
  const banked = player.titleProgress?.trapCleanDives ?? 0;

  if (banked >= 3) {
    getStore().appendLog('world', 'You have run the stair clean three times over — its traps hold no more names for you. (Shadow Diver is already yours.)');
    return;
  }

  // ── SCOUT (free) ──────────────────────────────────────────────────────────
  if (!isDive) {
    getStore().appendLog(
      'world',
      `The stair drops away into trap-laced dark. Each dive is a single d20 + DEX (yours: ${dex}) against DC ${dc} — read the pressure-plates and time the fall. ` +
      `Clean dives banked: ${banked}/3. (DIVE THE STAIR to attempt one — a miss springs the trap but costs you no run; you can dive again.)`,
    );
    return;
  }

  // ── DIVE (retryable) ──────────────────────────────────────────────────────
  const r = tc.rollCheck(dex, dc);
  const rollLine = `(d20 ${r.roll} + DEX ${dex} = ${r.total} vs DC ${dc})`;
  if (r.success) {
    const nowBanked = banked + 1;
    if (nowBanked >= 3) {
      getStore().appendLog('world', `You read the last plate a heartbeat before it reads you and roll clear onto the landing. Three dives, none sprung — you move through this place like it was built for you. ${rollLine}`);
    } else {
      getStore().appendLog('world', `You thread the dive clean — plates unsprung, rope true. That's ${nowBanked}/3. ${rollLine}`);
    }
    recordTitleProgress(getStore, setStore, { trapCleanDives: 1 });
  } else {
    const dmg = 1 + Math.floor(Math.random() * 6);
    const newHp = Math.max(1, player.hp - dmg); // non-lethal — the stair lets you try again
    setStore((s) => (s.player ? { player: { ...s.player, hp: newHp } } : s));
    getStore().appendLog('world', `A plate gives under your heel — a whir of darts, a dropped step. The trap springs for ${dmg} (${newHp}/${player.hpMax} HP). Still ${banked}/3 clean; steady yourself and dive again. ${rollLine}`);
    checkLowHpWarning(player.hp, newHp, player.hpMax ?? 1, getStore, setStore);
  }
}

// arb53 — Guild Broker (Parley Ground). Two non-allied faction leaders each
// demand their faction's coveted relic; fetch both and return to seal the
// alliance. No dice — a fetch-and-return, so it can't be failed. `seal` routes
// the turn-in; otherwise it's a (free) parley that opens / reports the mission.
function handleBroker(getStore: StoreGet, setStore: StoreSet, trimmed: string, seal: boolean): void {
  const player = getStore().player;
  if (!player) return;
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const broker = require('../engine/broker');
  const tileName = (id: string) => getLocationById(id)?.name ?? id;
  let mission = player.brokerMission;

  if (seal) {
    if (!mission) { getStore().appendLog('world', 'No parley is underway. Approach the leaders first.'); return; }
    if (mission.done) { getStore().appendLog('world', 'You have already brokered this alliance.'); return; }
    const legs = broker.missionLegs(mission);
    if (!legs) return;
    const has = (name: string) => player.inventory.some((i) => i.name === name);
    const missing = legs.filter((l: any) => !has(l.itemName));
    if (missing.length > 0) {
      getStore().appendLog('world',
        `The leaders wait. You still owe: ${missing.map((l: any) => `${l.itemName} for ${l.factionName} (at ${tileName(l.tileId)})`).join('; ')}.`);
      return;
    }
    // consume one of each relic, seal the pact
    let inv = player.inventory;
    for (const l of legs) {
      let removed = false;
      inv = inv
        .map((it) => {
          if (removed || it.name !== l.itemName) return it;
          removed = true;
          return { ...it, quantity: (it.quantity ?? 1) - 1 };
        })
        .filter((it) => (it.quantity ?? 1) > 0);
    }
    setStore((s) => (s.player ? { player: { ...s.player, inventory: inv, brokerMission: { ...mission!, done: true } } } : s));
    // OTA-506 — contract complete: flip both faction relic events "?" → "X".
    {
      const wm = getStore().worldMemory;
      let next = wm;
      for (const l of legs) next = setCanonLocationMarker(next, `contract_${(l as { factionId: string }).factionId}`, 'done');
      if (next !== wm) {
        setStore(() => ({ worldMemory: next }));
        setCanonExtraLocations(next.canonLocations ?? []);
      }
    }
    getStore().appendLog('world',
      `You lay both relics on the parley stone. ${legs[0].factionName} and ${legs[1].factionName} take their due — and, grudgingly, each other's hand. The alliance is brokered.`);
    recordTitleProgress(getStore, setStore, { alliancesBrokered: 1 });
    return;
  }

  // No mission yet — you STUMBLED onto the parley. OTA-656: don't silently take
  // the contract. Announce the offer + its demands and wait for ACCEPT / DECLINE.
  if (!mission) {
    const explicit = /\bparley\b/i.test(trimmed);
    // Already declined this offer? Ambient pokes (approach/examine) get a quiet
    // reminder, not a re-pop; only an explicit PARLEY re-opens the choice.
    if (player.brokerOfferDeclined && !explicit) {
      getStore().appendLog('world', 'The two leaders still wait on the neutral flats. PARLEY when you want to hear their terms.');
      return;
    }
    if (getStore().pendingMissionOffer) return; // offer already on screen
    const picked = broker.pickBrokerFactions(player.factionId, player.factionStanding ?? []);
    if (!picked) { getStore().appendLog('world', 'No two factions will sit with you on neutral ground right now.'); return; }
    // Build the demands preview from a provisional mission (NOT stored yet) so the
    // player can make an informed accept/decline choice.
    const provisional = { factionA: picked[0], factionB: picked[1] };
    const has0 = (name: string) => player.inventory.some((i) => i.name === name);
    const demands = broker.brokerMissionLine(provisional, has0, tileName)
      ?? `${broker.factionName(picked[0])} and ${broker.factionName(picked[1])} want to talk terms.`;
    const aName = broker.factionName(picked[0]);
    const bName = broker.factionName(picked[1]);
    setStore((s) => (s.player ? {
      player: { ...s.player, brokerOfferDeclined: false },
      pendingMissionOffer: {
        kind: 'broker', factionA: picked[0], factionB: picked[1],
        title: 'New mission — Broker an Alliance',
        body: `${demands}\n\nAccept to take this on as a tracked contract (you'll find it under CONTRACTS), or decline to walk away.`,
      },
    } : s));
    getStore().appendLog('mission',
      `Broker an Alliance: ${aName} and ${bName} are both here on the neutral flats, willing to talk terms — but brokering their alliance means fetching each faction's coveted relic. Accept the mission, or walk away?`);
    return;
  }
  if (mission.done) { getStore().appendLog('world', 'The alliance you brokered here holds.'); return; }
  const has = (name: string) => player.inventory.some((i) => i.name === name);
  const missionLine = broker.brokerMissionLine(mission, has, tileName);
  if (!missionLine) return;
  getStore().appendLog('world', missionLine);
}
// ⚠⚠ OTA-1397 — SLICE 6. THE QWEN WATCHDOG MOVED to `app/ai/qwenWatchdog.ts`.
//
// `runQwenHealthCheck` and `startQwenWatchdog` (268 lines) and the ten mutable
// `let`s that drive them — the poll timer, the AppState subscription, the
// reload counter, the backoff ladder, the in-flight clock, the true-background
// flag and the four log-once latches — now live beside the engine singletons
// slice 2 took down to `app/ai/engines.ts`.
//
// ⚠ IT NEEDED NO DEPS OBJECT, THE FIRST SLICE OF WHICH THAT IS TRUE. Everything
// it touches was already a leaf by the time it moved: the engine (slice 2), the
// memory-pressure latches (slice 5), the breadcrumb stamp, AppState. `get` and
// `set` were always parameters. The only flagged name, `narrateViaArbiter`,
// appears in those 268 lines exclusively inside a comment saying narration does
// NOT go through the watchdog — an injected dep nothing calls is a lie about
// coupling, so it was dropped, as `arbiterAddress` and
// `startRuntimePressureWatch` were in slices 3 and 4.
//
// ⚠⚠ AND WHAT gameStore KEEPS IS THE WIRING BETWEEN TWO LEAVES, deliberately.
// `startPressureWatchWithHooks` (see the top of this file) hands the pressure
// watch a GETTER for the reload count, which lives in the watchdog. If the
// pressure watch imported that counter directly instead, the two leaves would
// import each other — and a cycle between leaves is worse than one through the
// store, because neither file looks guilty when a binding resolves to
// `undefined` on a device. gameStore imports both and joins them; neither
// imports the other in the direction that would close the loop.


/** ⚠ OTA-1126 — the homework scheduler, installed at hydrate. Held at module
 *  scope for the same reason the telemetry sink is: the store is a closure and
 *  the driver below is a plain timer with no access to it. Null until hydrate
 *  runs, and a null tick is simply skipped — homework is the one subsystem that
 *  must never be load-bearing. */
let homeworkTickFn: (() => void) | null = null;
let homeworkTimer: ReturnType<typeof setInterval> | null = null;


// ⚠⚠ OTA-1360 — THE VENDOR-VOICE WARM SETTLES BEFORE IT LOADS. B9's answer, at
// last: freeze #4's tombstone (and a second one at 09:05 the same morning) both
// die SIGABRT inside the Kokoro voice LOAD on an executorch worker —
// fromModelName → native Kokoro ctor → phonemizer dictionary build, the second
// with 'Scudo ERROR: internal map failure (Out of memory)'. Freezes #2 and #5
// share the fingerprint that predicts it: FIRST entry into the messhall (R05, a
// vendor room) — beginScene fired warmVoice for Halem's voice synchronously
// inside the action pipeline, kicking off a hundreds-of-MB native allocation
// while the crumb still read `parsed:travel`. 400 jest replays could never see
// it: executorch is a mock here, and the killer only exists on the device.
//
// So the warm WAITS. A single timer (latest scene wins) fires after the player
// has actually stayed in the room a moment, and only then when three things
// hold: the room's vendor is still the current scene's vendor, the player is
// not sprinting (a sprinter's lines are dropped as stale anyway — a load per
// scene-flip is pure churn), and no memory-pressure cooldown is open. A skipped
// warm costs nothing but latency on the vendor's FIRST line — the speak path
// loads on demand — and a pass-through room now costs NOTHING at all.
const VENDOR_WARM_SETTLE_MS = 2_500;
let vendorWarmSettleTimer: ReturnType<typeof setTimeout> | null = null;

export function setHomeworkTick(fn: (() => void) | null): void {
  homeworkTickFn = fn;
  if (homeworkTimer !== null) { clearInterval(homeworkTimer); homeworkTimer = null; }
  if (!fn) return;
  // A slow poll on purpose. The tick itself is nearly free (a few guards and an
  // inventory scan) and the gate inside it decides everything; polling faster
  // would only burn wakeups to discover the same "not idle" answer.
  homeworkTimer = setInterval(() => {
    try { homeworkTickFn?.(); } catch { /* homework must never break the app */ }
  }, 5_000);
}
/** Tests only. */
export function _homeworkTickForTest(): void { homeworkTickFn?.(); }
export function _homeworkInstalled(): boolean { return homeworkTickFn !== null; }
/** OTA-1088 — guard-crack. Landing this many RESISTED hits of one damage type
 *  into one enemy wears its guard through: from the next swing on, that resist
 *  stops applying for the rest of the fight. Bounds the wrong-weapon slog — a
 *  resisted fight ends slower, not never — without flattening the damage-type
 *  system the way a global ×0.5 → ×0.75 soften would. The bestiary keeps
 *  recording the TRUE resist, so the knowledge layer never lies. */
const GUARD_CRACK_HITS = 3;

// ⚠⚠ OTA-1396 — SLICE 5. The runtime-pressure instruments MOVED to
// `app/diagnostics/runtimePressureWatch.ts` — the memory-warning counter, the
// AppState trail, both freeze clocks and the verdict that compares them.
//
// ⚠ FIVE of their mutable variables are shared with the Qwen watchdog below
// (the memory-pressure quiet window: when the OS says memory is tight, the
// watchdog stands Qwen down rather than reloading a ~400MB context). Shared
// mutable state cannot travel with either owner — assigning to an imported
// binding is a compile error — so it moved DOWN, and the watchdog now reads and
// writes it through the accessors that module exports.
//
// ⚠ `logUiTap` stayed, a few lines below: it touches no pressure state at all.

/** ⚠ THE BREADCRUMB. The freeze report had NO record of a tap between the last salvage and
 *  90 seconds of silence, so there was no way to tell "the tap never arrived" (screen
 *  frozen) from "the tap arrived and the work hung" (engine frozen). This is logged the
 *  instant a control is touched, BEFORE any work — that ordering is the entire point, and
 *  a future edit that moves it after the handler destroys the signal. */
export function logUiTap(label: string): void {
  try {
    // OTA-1695 — the touch's own wait (noteTouchDown at onPressIn) rides the line:
    // `ui: tap "dodge" ⏱+4237ms late 4200ms` says the screen held the finger, not the player.
    useGameStore.getState().appendLog('debug', `ui: tap "${label}"${takeTouchLateSuffix()}`);
    // ⚠⚠ OTA-1276 — AND STAMP IT WHERE A WEDGE CANNOT SWALLOW IT. The line
    // above goes into the BATCHED disk log, which drains on a promise chain —
    // and a wedged JS thread never drains it, so the last lines before a freeze
    // are lost and the log appears to end early. This single tiny write races
    // ahead of the wedge, so the next boot can name the last control touched.
    const st = useGameStore.getState();
    stampLiveBreadcrumb({
      at: Date.now(),
      what: `tap "${label}"`,
      screen: st.currentScreen,
      room: st.player?.hubRoomId ?? st.player?.currentLocationId ?? undefined,
    });
  } catch { /* never let instrumentation break a control */ }
}


