  raiseSpotlightNotice: (
    heading: string, title: string, flavor: string[], rewards: string[],
    /** OTA-1163 — presentation only; see missionCompleteNotice. */
    opts?: { takeLabel?: string; holdMs?: number },
  ) => void;
