  resolveCrucibleGuard: (mode: CrucibleGuardMode, ids?: readonly string[]) => void;

  bootCognitive: () => Promise<void>;
  shutdownCognitive: () => Promise<void>;
  resumeCognitive: () => Promise<void>;

